INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C1','kor',1,2,'u4',3,'이야기의 인물과 인물이 한 일 알기 — 누가 나오는지 찾기, 인물의 생각·말·행동을 보고 무엇을 했는지 알기, 이야기에 없는 일은 넣지 않기',ARRAY['2국05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C2','kor',1,2,'u4',6,'시간을 나타내는 말로 일의 차례 정리하기 — 아침·낮·저녁·이듬해처럼 「언제」에 답이 되는 말을 찾아 먼저 있었던 일과 나중에 있었던 일을 차례대로 늘어놓기, 왜 그런 일이 있었는지 함께 생각하기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C3','kor',1,2,'u4',6,'큰따옴표와 작은따옴표 알기 — 소리 내어 한 말에는 큰따옴표 “ ”, 마음속으로 한 말에는 작은따옴표 ‘ ’, 글자 칸 위쪽에 붙여 쓰기',ARRAY['2국04-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C4','kor',1,2,'u4',8,'만화 영화의 이야기를 차례대로 정리하기 — 장면 카드에서 누가 나오는지 알고, 언제·누가·무엇을 했는지를 넣어 있었던 일을 차례대로 정리하기, 화면 크기·글자 수처럼 이야기와 상관없는 것은 빼기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C5','kor',1,2,'u4',10,'감동을 까닭과 함께 나누기 — 마음이 움직인 장면을 「왜 그렇게 느꼈는지」 까닭과 함께 내 말로 말하기, 까닭은 인물이 한 일에서 찾기, 사람마다 감동이 다르다는 것을 알고 친구의 다른 반응을 존중하기, 따라 말하거나 한마디로 끝내지 않기',ARRAY['2국05-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C6','kor',1,2,'u4',12,'감동한 장면을 그림으로 나타내고 감상하기 — 말하기→그리기→나누기 세 걸음, 인물과 인물이 한 일이 드러나는 한 장면 그리기, 그림 옆에 어떤 장면을 왜 그렸는지 쓰기, 친구 그림을 견주며 존중하며 보기',ARRAY['2국05-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u4-C7','kor',1,2,'u4',14,'동작을 나타내는 말 알기 — 「무엇을 한다」에 쓰는 움직임 말(넘습니다·닫습니다·찹니다)을 찾고, 그림에 맞는 동작 말을 문장에 넣기(기초 다지기)',ARRAY['2국04-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X01','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C4']::text[],'인물이 무엇을 했는지를 생각·말·행동이 아니라 겉모습(옷·키·머리)으로 찾으려 한다','「무슨 옷을 입었는지로 무엇을 했는지 알 수 있나요?」 인물이 한 말 한 줄, 한 행동 한 줄을 손가락으로 짚게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X02','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C4']::text[],'이야기에 없던 일을 있었던 일로 넣는다(내 마음대로 정한 것)','「그 일이 글 어디에 있나요?」 글에서 그 줄을 찾아 보게 하고, 없으면 넣지 않기로 약속하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X03','kor',1,'u4',ARRAY['K1-2-u4-C1','K1-2-u4-C4']::text[],'이야기에 나오지 않는 사람이나 물건·장소를 인물이라고 한다','인물 이름을 글에서 동그라미 치게 하고 「이 사람이 글에 나오나요?」 되묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X04','kor',1,'u4',ARRAY['K1-2-u4-C2','K1-2-u4-C4']::text[],'시간을 나타내는 말이 아닌 것(장소·느낌·물건)을 때를 알려 주는 말로 고른다','「언제?」 하고 물었을 때 대답이 되는 말인지 확인하게 하기 — 「화단에서」는 「어디에서」의 대답') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X05','kor',1,'u4',ARRAY['K1-2-u4-C2','K1-2-u4-C4']::text[],'먼저 있었던 일과 나중에 있었던 일을 바꾸거나 마음대로 늘어놓는다','아침·낮·저녁 카드를 먼저 줄 세우고 그 밑에 일을 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X06','kor',1,'u4',ARRAY['K1-2-u4-C3']::text[],'큰따옴표와 작은따옴표를 바꾸어 쓴다(마음속 말에 큰따옴표)','「입으로 소리 냈나요, 마음속으로 했나요?」 입을 가리키면 큰따옴표, 가슴을 가리키면 작은따옴표로 몸으로 익히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X07','kor',1,'u4',ARRAY['K1-2-u4-C3']::text[],'따옴표를 쓰는 자리나 모양을 틀린다(칸 아래쪽에 쓰거나 한쪽만 쓴다)','따옴표는 칸 위쪽에 붙여, 열고 닫는 두 짝을 함께 쓴다는 것을 따라 쓰며 익히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X08','kor',1,'u4',ARRAY['K1-2-u4-C4']::text[],'만화 영화를 볼 때 화면 크기·글자 수·색깔 수처럼 이야기와 상관없는 것을 살핀다','「그걸 알면 무슨 일이 있었는지 알 수 있나요?」 인물·한 일로 다시 눈을 돌리게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X09','kor',1,'u4',ARRAY['K1-2-u4-C4','K1-2-u4-C2']::text[],'있었던 일을 정리할 때 언제·누가·무엇을 가운데 하나를 빠뜨린다','세 손가락(언제·누가·무엇을)을 펴고 한 칸씩 접으며 빠진 칸 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X10','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'「재미있었다」·「감동이었다」 한마디만 말하고 까닭을 말하지 않는다','「무엇이 어떻게?」 하고 되물어 인물이 한 일에서 까닭 한 가지를 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X11','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'친구가 말한 느낌을 그대로 따라 말하거나 외운 말로 말한다','「네 마음은 어디에서 움직였어?」 친구와 다른 장면을 골라도 된다고 먼저 말해 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X12','kor',1,'u4',ARRAY['K1-2-u4-C5','K1-2-u4-C6']::text[],'나와 다른 장면을 고른 친구에게 틀렸다고 하거나 고치려 한다','「사람마다 겪은 일이 달라서 마음이 움직이는 곳도 달라요」 — 친구에게 왜 그 장면인지 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X13','kor',1,'u4',ARRAY['K1-2-u4-C5']::text[],'감동의 까닭을 인물이 한 일이 아니라 만화의 길이·색깔·그림 솜씨에서 찾는다','「그 인물이 무엇을 했길래 마음이 움직였나요?」 까닭을 인물의 말·행동에서 찾게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X14','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'그림을 예쁘게 그리기·테두리 꾸미기 겨루기로 여겨 장면이 안 드러난다','「이 그림만 보고 어떤 장면인지 알 수 있나요?」 인물과 한 일이 보이면 된다고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X15','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'그림에 인물과 인물이 한 일이 드러나지 않는다(배경만·물건만)','그림 옆에 「누가 무엇을 하는 장면」 한 줄을 먼저 쓰고 그리게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X16','kor',1,'u4',ARRAY['K1-2-u4-C6']::text[],'친구 그림을 볼 때 누가 더 잘 그렸는지 고르거나 흉을 본다','「어떤 장면을 골랐는지, 왜 골랐는지」 한 가지씩 물어보게 하고 견주는 말은 받지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u4-X17','kor',1,'u4',ARRAY['K1-2-u4-C7']::text[],'동작을 나타내는 말과 아닌 말(이름·모양·느낌 말)을 가르지 못한다','「몸으로 해 볼 수 있나요?」 동작 말은 몸으로 흉내 내 보게 하기 — 「책상」은 못 하지만 「닫습니다」는 할 수 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#1','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','「공원의 비둘기」에 나오는 사람은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],true,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「공원의 비둘기」에 나오는 사람은 누구인가요?","options":[{"t":"서아와 엄마","correct":true},{"t":"서아와 선생님","mis":"K1-2-u4-X03"},{"t":"지후와 할머니","mis":"K1-2-u4-X03"}],"explanation":["서아와 엄마가 공원에 갔어요.","선생님이나 지후는 이 글에 나오지 않아요.","글에서 이름을 찾아요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"},"variant_rule":{"alt":[{"stem":"「종이배 경주」에 나오는 사람은 누구인가요?","options":[{"t":"민솔이와 형","correct":true},{"t":"민솔이와 엄마","mis":"K1-2-u4-X03"},{"t":"서아와 할머니","mis":"K1-2-u4-X03"}],"explanation":["민솔이와 형이 종이배를 띄웠어요.","엄마나 서아는 이 글에 없어요.","글에서 이름을 찾아요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#2','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','「공원의 비둘기」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「공원의 비둘기」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"토요일 아침","correct":true},{"t":"공원에","mis":"K1-2-u4-X04"},{"t":"비둘기가","mis":"K1-2-u4-X04"}],"explanation":["「토요일 아침」은 언제인지 알려 줘요.","「공원에」는 어디에서, 「비둘기가」는 누가예요.","「언제?」에 답이 되는 말을 찾아요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#3','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','이야기를 알아볼 때 가장 먼저 살펴볼 것은 무엇인가요?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":3,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"이야기를 알아볼 때 가장 먼저 살펴볼 것은 무엇인가요?","options":[{"t":"누가 나오고 무엇을 했는지","correct":true},{"t":"글자가 몇 개인지","mis":"K1-2-u4-X08"},{"t":"종이가 무슨 색인지","mis":"K1-2-u4-X08"}],"explanation":["인물과 인물이 한 일부터 살펴봐요.","글자 수나 종이 색은 이야기와 상관없어요.","이야기에는 꼭 인물이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#4','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','기억에 남는 장면을 말하는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u4-X11','K1-2-u4-X10']::text[],false,'{"seq":4,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"기억에 남는 장면을 말하는 알맞은 방법은 어느 것인가요?","options":[{"t":"어느 장면인지와 왜 그런지 까닭을 함께 말한다","correct":true},{"t":"친구가 한 말을 그대로 따라 말한다","mis":"K1-2-u4-X11"},{"t":"「재미있었다」 한마디만 한다","mis":"K1-2-u4-X10"}],"explanation":["장면과 까닭을 함께 말해요.","따라 말하거나 한마디만 하면 내 마음이 전해지지 않아요.","「왜냐하면」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#5','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C2',2,'mc','auto','「공원의 비둘기」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],true,'{"seq":5,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「공원의 비둘기」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"서아가 엄마와 공원에 갔다","correct":true},{"t":"서아가 집에서 비둘기를 그렸다","mis":"K1-2-u4-X05"},{"t":"비둘기가 빵을 먹고 날아갔다","mis":"K1-2-u4-X05"}],"explanation":["「토요일 아침」에 공원에 간 일이 처음이에요.","그림을 그린 일은 「저녁」, 빵을 먹은 일은 그 사이예요.","때를 알려 주는 말을 따라가요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"},"variant_rule":{"alt":[{"stem":"「공원의 비둘기」에서 가장 나중에 있었던 일은 무엇인가요?","options":[{"t":"서아가 집에서 비둘기를 그렸다","correct":true},{"t":"서아가 엄마와 공원에 갔다","mis":"K1-2-u4-X05"},{"t":"비둘기가 서아 발 앞에 앉았다","mis":"K1-2-u4-X05"}],"explanation":["「저녁에」 그림을 그린 일이 마지막이에요.","공원에 간 일과 비둘기가 앉은 일은 그 앞이에요.","때를 알려 주는 말을 따라가요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#6','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C2',2,'match','auto','「공원의 비둘기」에서 때와 그때 있었던 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"「공원의 비둘기」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"토요일 아침","r":"공원에 갔다"},{"l":"낮","r":"비둘기가 발 앞에 앉았다"},{"l":"저녁","r":"집에서 비둘기를 그렸다"}],"mis":"K1-2-u4-X05","explanation":["아침에 공원에 갔어요.","낮에 비둘기가 앉고, 저녁에 그림을 그렸어요.","글에서 때를 알려 주는 말 옆을 봐요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"},"variant_rule":{"alt":[{"stem":"「종이배 경주」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"일요일 낮","r":"개울에서 종이배를 띄웠다"},{"l":"저녁","r":"두 배가 개울 끝에 닿았다"}],"explanation":["낮에 종이배를 띄웠어요.","저녁에 두 배가 개울 끝에 닿았어요.","때를 알려 주는 말 옆을 봐요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#7','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','「공원의 비둘기」에서 서아가 한 말은 어느 것인가요?',ARRAY['K1-2-u4-X02','K1-2-u4-X01']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「공원의 비둘기」에서 서아가 한 말은 어느 것인가요?","options":[{"t":"배가 고픈가 봐.","correct":true},{"t":"빵을 다 먹었어.","mis":"K1-2-u4-X02"},{"t":"또 만나고 싶다.","mis":"K1-2-u4-X01"}],"explanation":["서아는 \"배가 고픈가 봐.\" 하고 말했어요.","「또 만나고 싶다」는 마음속으로 한 생각이에요.","소리 내어 한 말은 큰따옴표 안에 있어요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#8','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','친구가 나와 다른 장면을 골랐어요. 어떻게 하면 좋을까요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":8,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 장면을 골랐어요. 어떻게 하면 좋을까요?","options":[{"t":"그럴 수 있다고 생각하고 왜 그런지 까닭을 들어 본다","correct":true},{"t":"틀렸다고 말해 준다","mis":"K1-2-u4-X12"},{"t":"내 장면으로 바꾸게 한다","mis":"K1-2-u4-X12"}],"explanation":["사람마다 마음이 움직이는 곳이 달라요.","틀렸다고 하거나 바꾸게 하면 안 돼요.","까닭을 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#9','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C1',2,'ox','auto','이야기를 담아 보여 주는 것에는 책뿐 아니라 만화 영화도 있어요.',ARRAY['K1-2-u4-X08']::text[],true,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"ox","stem":"이야기를 담아 보여 주는 것에는 책뿐 아니라 만화 영화도 있어요.","answer":"O","reason_options":[{"t":"만화 영화도 인물이 나오고 일이 차례대로 이어지니까","correct":true},{"t":"만화 영화에는 글자가 없으니까","mis":"K1-2-u4-X08"}],"mis":"K1-2-u4-X08","explanation":["책도 만화 영화도 이야기를 담아요.","글자가 있고 없고는 상관없어요.","움직이는 그림과 소리로 이야기를 전해요."],"variant_rule":{"alt":[{"stem":"이야기에는 인물이 나오고, 인물이 한 일이 차례대로 이어져요.","answer":"O","reason_options":[{"t":"인물과 차례를 살펴보면 이야기가 잘 보이니까","correct":true},{"t":"이야기는 글자가 많으니까","mis":"K1-2-u4-X08"}],"explanation":["인물과 차례가 이야기의 뼈대예요.","글자 수는 상관없어요.","누가 무엇을 했는지부터."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_basic#10','kor',1,2,'u4','L01','g1_2_kor_u4_L01_basic','lesson_basic','K1-2-u4-C5',3,'error','auto','기억에 남는 장면을 말하는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#1','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C1',2,'mc','auto','「종이배 경주」에서 형이 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「종이배 경주」에서 형이 한 일은 무엇인가요?","options":[{"t":"나뭇가지로 종이배를 밀어 주었다","correct":true},{"t":"종이배를 접어 주었다","mis":"K1-2-u4-X02"},{"t":"개울에서 물고기를 잡았다","mis":"K1-2-u4-X02"}],"explanation":["형은 \"내가 밀어 줄게.\" 하고 배를 밀었어요.","배를 접어 준 일이나 물고기 잡은 일은 글에 없어요.","글에서 형이 한 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#2','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C2',2,'mc','auto','「종이배 경주」에서 때를 알려 주는 말을 모두 고른 것은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「종이배 경주」에서 때를 알려 주는 말을 모두 고른 것은 어느 것인가요?","options":[{"t":"일요일 낮 · 저녁","correct":true},{"t":"개울 · 돌","mis":"K1-2-u4-X04"},{"t":"종이배 · 나뭇가지","mis":"K1-2-u4-X04"}],"explanation":["「일요일 낮」·「저녁」이 때를 알려 줘요.","개울·돌은 어디에서, 종이배·나뭇가지는 무엇이에요.","「언제?」에 답이 되는 말."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#3','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',3,'mc','auto','까닭을 함께 말한 친구는 누구인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":3,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"까닭을 함께 말한 친구는 누구인가요?","options":[{"t":"나린 — 비를 맞으면서도 할머니를 먼저 생각해서 그 장면이 남았다고 말했다","correct":true},{"t":"도윤 — 장면만 말하고 끝냈다","mis":"K1-2-u4-X10"},{"t":"둘 다 까닭을 말하지 않았다","mis":"K1-2-u4-X10"}],"explanation":["나린이는 「왜냐하면」에 해당하는 까닭을 붙였어요.","도윤이도 「고마운 마음이 느껴져서」라고 까닭을 말했어요.","장면 뒤에 오는 말을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「작은 우산」에서 어느 장면이 가장 마음에 남았나요?"},{"who":"나린","text":"지후가 우산을 씌워 드린 장면이요. 비를 맞으면서도 할머니를 먼저 생각해서요."},{"who":"도윤","text":"나는 할머니가 손을 흔든 장면이요. 고마운 마음이 느껴졌어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#4','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C1',3,'mc','auto','「종이배 경주」에 없었던 일은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],true,'{"seq":4,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"「종이배 경주」에 없었던 일은 어느 것인가요?","options":[{"t":"민솔이가 형의 배를 밀어 주었다","correct":true},{"t":"민솔이의 배가 돌에 걸렸다","mis":"K1-2-u4-X02"},{"t":"두 배가 나란히 개울 끝에 닿았다","mis":"K1-2-u4-X02"}],"explanation":["배를 밀어 준 사람은 형이에요.","돌에 걸린 일, 나란히 닿은 일은 글에 있어요.","누가 했는지 바꾸면 안 돼요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"},"variant_rule":{"alt":[{"stem":"「공원의 비둘기」에 없었던 일은 어느 것인가요?","options":[{"t":"서아가 비둘기를 집에 데려왔다","correct":true},{"t":"비둘기가 서아 발 앞에 앉았다","mis":"K1-2-u4-X02"},{"t":"엄마가 빵 조각을 떼어 주셨다","mis":"K1-2-u4-X02"}],"explanation":["비둘기는 날아갔어요.","발 앞에 앉은 일, 빵을 준 일은 글에 있어요.","글에 없는 일은 넣지 않아요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#5','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C2',3,'error','auto','「종이배 경주」에서 일이 일어난 차례를 늘어놓았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#6','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',3,'ox','auto','「재미있었다」 한마디만 말하면 듣는 사람은 무엇이 어떻게 좋았는지 알 수 없어요.',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"「재미있었다」 한마디만 말하면 듣는 사람은 무엇이 어떻게 좋았는지 알 수 없어요.","answer":"O","reason_options":[{"t":"까닭이 없으면 내 마음이 어디에서 움직였는지 전해지지 않으니까","correct":true},{"t":"한마디로 말하면 발표가 짧아지니까","mis":"K1-2-u4-X10"}],"mis":"K1-2-u4-X10","explanation":["무엇이 어떻게 좋았는지 까닭을 붙여요.","짧아서 문제가 아니라 마음이 안 보여서 문제예요.","선생님이 왜 되물었는지 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이야기를 보고 어땠나요?"},{"who":"민솔","text":"재미있었어요."},{"who":"선생님","text":"무엇이 어떻게 재미있었나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#7','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C1',3,'match','auto','「공원의 비둘기」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":3,"kind":"match","stem":"「공원의 비둘기」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.","pairs":[{"l":"서아","r":"비둘기를 그렸다"},{"l":"엄마","r":"빵 조각을 떼어 주었다"},{"l":"비둘기","r":"빵을 먹고 날아갔다"}],"mis":"K1-2-u4-X02","explanation":["서아는 저녁에 비둘기를 그렸어요.","엄마는 빵을 주셨고, 비둘기는 먹고 날아갔어요.","인물마다 한 일이 달라요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#8','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C2',4,'sa','auto','「종이배 경주」에서 두 배가 개울 끝에 닿은 때를 알려 주는 말을 글에서 찾아 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u4-C2","difficulty":4,"kind":"sa","stem":"「종이배 경주」에서 두 배가 개울 끝에 닿은 때를 알려 주는 말을 글에서 찾아 쓰세요.","answer":["저녁","저녁이 되자","저녁에"],"explanation":["「저녁이 되자 두 배는 나란히 개울 끝에 닿았다」예요.","「언제?」에 답이 되는 말이에요.","그 문장 맨 앞을 봐요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"},"variant_rule":{"alt":[{"stem":"「공원의 비둘기」에서 비둘기가 서아 발 앞에 앉은 때를 알려 주는 말을 글에서 찾아 쓰세요.","answer":["낮","낮이 되자","낮에"],"explanation":["「낮이 되자 비둘기 한 마리가 발 앞에 앉았다」예요.","「언제?」에 답이 되는 말이에요.","그 문장 맨 앞을 봐요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#9','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','「공원의 비둘기」에서 기억에 남는 장면 하나를 고르고, 왜 그 장면이 남았는지 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「공원의 비둘기」에서 기억에 남는 장면 하나를 고르고, 왜 그 장면이 남았는지 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 서아가 비둘기에게 빵을 주는 장면이 남았다. 배고픈 비둘기를 그냥 지나치지 않아서 마음이 따뜻해졌다. — 장면 하나와 까닭이 있으면 맞아요(어느 장면을 골라도 좋아요).","scoring_points":["장면이 하나 있는가","까닭(왜냐하면)이 있는가","내 말로 썼는가"]},"explanation":["장면과 까닭을 함께 써요.","어느 장면을 골라도 좋아요.","「왜냐하면」을 붙여요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L01_challenge#10','kor',1,2,'u4','L01','g1_2_kor_u4_L01_challenge','lesson_challenge','K1-2-u4-C1',4,'essay','teacher','「종이배 경주」에서 누가 무엇을 했는지 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"「종이배 경주」에서 누가 무엇을 했는지 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 형이 나뭇가지로 멈춘 종이배를 밀어 주었다. — 인물 이름과 그 인물이 한 일이 들어 있으면 맞아요(민솔이가 종이배를 띄웠다도 좋아요).","scoring_points":["인물 이름이 있는가","그 인물이 한 일이 글에 있는 일인가","한 문장인가"]},"explanation":["누가, 무엇을 했는지를 넣어요.","글에 있는 일만 써요.","인물 이름부터."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#1','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','「씨앗 심은 날」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],true,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」에 나오는 인물은 누구인가요?","options":[{"t":"나린, 도윤, 선생님","correct":true},{"t":"나린, 도윤, 할머니","mis":"K1-2-u4-X03"},{"t":"서아, 지후, 선생님","mis":"K1-2-u4-X03"}],"explanation":["「나」는 나린이고, 도윤이와 선생님이 함께 나와요.","할머니·서아·지후는 이 글에 없어요.","글에서 이름을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"},"variant_rule":{"alt":[{"stem":"「작은 우산」에 나오는 인물은 누구인가요?","options":[{"t":"지후와 할머니","correct":true},{"t":"지후와 엄마","mis":"K1-2-u4-X03"},{"t":"나린과 할머니","mis":"K1-2-u4-X03"}],"explanation":["지후와 할머니가 정류장에서 만났어요.","엄마나 나린이는 이 글에 없어요.","글에서 이름을 찾아요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#2','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','「씨앗 심은 날」은 언제 있었던 일인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」은 언제 있었던 일인가요?","options":[{"t":"지난 월요일 아침","correct":true},{"t":"오늘 저녁","mis":"K1-2-u4-X02"},{"t":"지난 토요일 밤","mis":"K1-2-u4-X02"}],"explanation":["「지난 월요일 아침」에 화단에 나갔어요.","저녁이나 토요일은 글에 없어요.","첫 줄의 때를 알려 주는 말을 봐요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#3','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','인물이 무엇을 했는지 알려면 무엇을 살펴보면 될까요?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":3,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"인물이 무엇을 했는지 알려면 무엇을 살펴보면 될까요?","options":[{"t":"인물의 생각과 말, 행동","correct":true},{"t":"인물의 옷 색깔","mis":"K1-2-u4-X01"},{"t":"인물의 키","mis":"K1-2-u4-X01"}],"explanation":["생각·말·행동을 보면 무엇을 했는지 알 수 있어요.","옷이나 키를 아무리 봐도 무엇을 했는지는 몰라요.","세 가지를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#4','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',1,'mc','auto','「씨앗 심은 날」에서 도윤이가 한 말은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":4,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」에서 도윤이가 한 말은 어느 것인가요?","options":[{"t":"내가 구멍을 팔게.","correct":true},{"t":"싹이 나면 함께 보자.","mis":"K1-2-u4-X02"},{"t":"빨리 싹이 났으면.","mis":"K1-2-u4-X02"}],"explanation":["도윤이가 \"내가 구멍을 팔게.\" 하고 말했어요.","「싹이 나면 함께 보자」는 선생님 말씀, 「빨리 싹이 났으면」은 나린이의 생각이에요.","누가 한 말인지 앞을 봐요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#5','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','「씨앗 심은 날」에서 나린이가 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],true,'{"seq":5,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「씨앗 심은 날」에서 나린이가 한 일은 무엇인가요?","options":[{"t":"씨앗을 넣고 흙을 덮었다","correct":true},{"t":"구멍을 팠다","mis":"K1-2-u4-X02"},{"t":"물을 주었다","mis":"K1-2-u4-X02"}],"explanation":["「나」인 나린이는 씨앗을 넣고 흙을 살살 덮었어요.","구멍을 판 것과 물을 준 것은 도윤이가 한 일이에요.","「나는」으로 시작하는 줄을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"},"variant_rule":{"alt":[{"stem":"「씨앗 심은 날」에서 선생님께서 하신 일은 무엇인가요?","options":[{"t":"씨앗을 한 알씩 나누어 주셨다","correct":true},{"t":"구멍을 파셨다","mis":"K1-2-u4-X02"},{"t":"물을 주셨다","mis":"K1-2-u4-X02"}],"explanation":["선생님께서 씨앗을 나누어 주셨어요.","구멍 파기와 물 주기는 도윤이가 했어요.","「선생님께서」로 시작하는 줄을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#6','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'match','auto','「씨앗 심은 날」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「씨앗 심은 날」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.","pairs":[{"l":"나린","r":"흙을 살살 덮었다"},{"l":"도윤","r":"물뿌리개로 물을 주었다"},{"l":"선생님","r":"씨앗을 나누어 주셨다"}],"mis":"K1-2-u4-X02","explanation":["나린이는 흙을 덮었어요.","도윤이는 물을 주고, 선생님은 씨앗을 나누어 주셨어요.","인물마다 한 일이 달라요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"},"variant_rule":{"alt":[{"stem":"「작은 우산」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.","pairs":[{"l":"지후","r":"우산을 씌워 드렸다"},{"l":"할머니","r":"손을 흔들며 버스를 탔다"}],"explanation":["지후는 우산을 씌워 드렸어요.","할머니는 손을 흔들며 버스를 타셨어요.","인물마다 한 일이 달라요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#7','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','「씨앗 심은 날」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「씨앗 심은 날」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"우리 반이 화단에 나갔다","correct":true},{"t":"도윤이가 물을 주었다","mis":"K1-2-u4-X05"},{"t":"나린이가 흙을 덮었다","mis":"K1-2-u4-X05"}],"explanation":["화단에 나간 일이 첫 줄에 있어요.","물 주기와 흙 덮기는 그 뒤에 있었던 일이에요.","글의 첫 줄부터 봐요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#8','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'ox','auto','「씨앗 심은 날」에서 도윤이가 흙을 덮었어요.',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":8,"concept":"K1-2-u4-C1","difficulty":2,"kind":"ox","stem":"「씨앗 심은 날」에서 도윤이가 흙을 덮었어요.","answer":"X","reason_options":[{"t":"흙을 덮은 사람은 「나」인 나린이니까","correct":true},{"t":"도윤이가 구멍을 팠으니까 흙도 덮었을 거니까","mis":"K1-2-u4-X02"}],"mis":"K1-2-u4-X02","explanation":["흙을 덮은 사람은 나린이에요.","글에 없는 일을 짐작해서 넣으면 안 돼요.","「나는 씨앗을 넣고 흙을 살살 덮었다」를 봐요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#9','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',2,'mc','auto','「작은 우산」에서 지후가 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「작은 우산」에서 지후가 한 일은 무엇인가요?","options":[{"t":"할머니께 우산을 씌워 드렸다","correct":true},{"t":"할머니와 버스를 탔다","mis":"K1-2-u4-X02"},{"t":"할머니께 우산을 선물했다","mis":"K1-2-u4-X02"}],"explanation":["지후는 할머니 옆에 서서 우산을 씌워 드렸어요.","버스를 함께 타거나 선물한 일은 글에 없어요.","지후의 행동을 찾아요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_basic#10','kor',1,2,'u4','L03','g1_2_kor_u4_L03_basic','lesson_basic','K1-2-u4-C1',3,'error','auto','「작은 우산」에서 있었던 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#1','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',2,'mc','auto','「작은 우산」에서 할머니가 한 말은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「작은 우산」에서 할머니가 한 말은 어느 것인가요?","options":[{"t":"고맙다, 꼬마야.","correct":true},{"t":"그래도 참 잘했어.","mis":"K1-2-u4-X02"},{"t":"비가 많이 오는구나.","mis":"K1-2-u4-X02"}],"explanation":["할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨어요.","「그래도 참 잘했어」는 지후가 마음속으로 한 생각이에요.","큰따옴표 안의 말을 봐요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#2','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',2,'mc','auto','「작은 우산」에서 지후가 마음속으로 한 생각은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C1","difficulty":2,"kind":"mc","stem":"「작은 우산」에서 지후가 마음속으로 한 생각은 어느 것인가요?","options":[{"t":"그래도 참 잘했어.","correct":true},{"t":"고맙다, 꼬마야.","mis":"K1-2-u4-X02"},{"t":"버스가 늦게 오네.","mis":"K1-2-u4-X02"}],"explanation":["지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했어요.","「고맙다, 꼬마야」는 할머니가 소리 내어 한 말이에요.","작은따옴표 안의 말을 봐요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#3','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'mc','auto','「씨앗 심은 날」에서 나린이의 마음을 알 수 있는 부분은 어느 것인가요?',ARRAY['K1-2-u4-X01']::text[],false,'{"seq":3,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"「씨앗 심은 날」에서 나린이의 마음을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"빨리 싹이 났으면. 하고 생각한 것","correct":true},{"t":"씨앗을 넣고 흙을 덮은 것","mis":"K1-2-u4-X01"},{"t":"우리 반이 화단에 나간 것","mis":"K1-2-u4-X01"}],"explanation":["마음속으로 한 생각에서 마음이 보여요.","흙을 덮은 것과 화단에 나간 것은 한 일이지 마음은 아니에요.","생각을 적은 줄을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#4','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'mc','auto','「씨앗 심은 날」을 읽고 알 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],true,'{"seq":4,"concept":"K1-2-u4-C1","difficulty":3,"kind":"mc","stem":"「씨앗 심은 날」을 읽고 알 수 있는 것은 어느 것인가요?","options":[{"t":"나린이와 도윤이가 함께 씨앗을 심었다","correct":true},{"t":"나린이와 도윤이가 싹을 보았다","mis":"K1-2-u4-X02"},{"t":"도윤이가 씨앗을 사 왔다","mis":"K1-2-u4-X02"}],"explanation":["둘이 나누어 씨앗을 심은 일이 글에 있어요.","싹은 아직 안 났고, 씨앗은 선생님께서 주셨어요.","글에 있는 일만 골라요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"},"variant_rule":{"alt":[{"stem":"「작은 우산」을 읽고 알 수 있는 것은 어느 것인가요?","options":[{"t":"지후는 비를 조금 맞았지만 잘한 일이라고 생각했다","correct":true},{"t":"지후는 우산을 잃어버렸다","mis":"K1-2-u4-X02"},{"t":"할머니는 지후를 혼내셨다","mis":"K1-2-u4-X02"}],"explanation":["옷이 젖었어도 「참 잘했어」라고 생각했어요.","우산을 잃어버리거나 혼난 일은 없어요.","글에 있는 일만."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#5','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'error','auto','인물이 한 일을 알려고 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#6','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'match','auto','「작은 우산」에서 말·행동·생각과 그 내용을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C1","difficulty":3,"kind":"match","stem":"「작은 우산」에서 말·행동·생각과 그 내용을 선으로 이어 보세요.","pairs":[{"l":"할머니가 한 말","r":"고맙다, 꼬마야."},{"l":"지후가 한 행동","r":"우산을 씌워 드렸다"},{"l":"지후가 한 생각","r":"그래도 참 잘했어."}],"mis":"K1-2-u4-X01","explanation":["소리 내어 한 말은 큰따옴표 안에 있어요.","행동은 몸으로 한 일, 생각은 작은따옴표 안이에요.","세 가지를 가려요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#7','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',3,'ox','auto','「씨앗 심은 날」에서 선생님께서 "싹이 나면 함께 보자." 하고 말씀하신 것은 글에 있는 일이에요.',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":3,"kind":"ox","stem":"「씨앗 심은 날」에서 선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하신 것은 글에 있는 일이에요.","answer":"O","reason_options":[{"t":"글에 그 말이 큰따옴표 안에 적혀 있으니까","correct":true},{"t":"선생님은 늘 그렇게 말씀하시니까","mis":"K1-2-u4-X02"}],"mis":"K1-2-u4-X02","explanation":["글에 적혀 있는 말이에요.","늘 그런다는 짐작이 아니라 글을 보고 말해요.","큰따옴표 안을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#8','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'sa','auto','「씨앗 심은 날」에서 물뿌리개로 물을 준 사람의 이름을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u4-C1","difficulty":4,"kind":"sa","stem":"「씨앗 심은 날」에서 물뿌리개로 물을 준 사람의 이름을 쓰세요.","answer":["도윤","도윤이"],"explanation":["「낮에 도윤이는 물뿌리개로 물을 주었다」예요.","나린이는 흙을 덮었어요.","물을 준 줄을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"},"variant_rule":{"alt":[{"stem":"「작은 우산」에서 \"고맙다, 꼬마야.\" 하고 말한 사람은 누구인지 쓰세요.","answer":["할머니","할머니가"],"explanation":["할머니가 웃으며 하신 말이에요.","지후는 마음속으로 생각했어요.","큰따옴표 앞뒤를 봐요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#9','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'essay','teacher','「작은 우산」에서 지후가 한 일과 그 일을 하고 나서 한 생각을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"「작은 우산」에서 지후가 한 일과 그 일을 하고 나서 한 생각을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 지후는 비를 맞는 할머니께 우산을 씌워 드렸다. 그리고 집에 와서 참 잘했다고 생각했다. — 한 일과 생각이 글에 있는 대로 들어 있으면 맞아요.","scoring_points":["지후가 한 일이 글에 있는 일인가","지후의 생각이 들어 있는가","두 문장인가"]},"explanation":["행동과 생각을 하나씩 써요.","글에 있는 대로 써요.","작은따옴표 안을 봐요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L03_challenge#10','kor',1,2,'u4','L03','g1_2_kor_u4_L03_challenge','lesson_challenge','K1-2-u4-C1',4,'essay','teacher','「씨앗 심은 날」에서 도윤이가 한 말과 행동을 보고, 도윤이는 어떤 친구인지 까닭과 함께 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":4,"kind":"essay","stem":"「씨앗 심은 날」에서 도윤이가 한 말과 행동을 보고, 도윤이는 어떤 친구인지 까닭과 함께 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 도윤이는 먼저 나서서 돕는 친구다. 구멍을 팔게 하고 말하고 물까지 주었기 때문이다. — 글에 있는 말이나 행동을 까닭으로 들었으면 맞아요.","scoring_points":["도윤이의 말이나 행동을 까닭으로 들었는가","글에 있는 일인가","어떤 친구인지가 있는가"]},"explanation":["말과 행동에서 인물을 알 수 있어요.","「내가 구멍을 팔게」와 물 주기를 떠올려요.","까닭은 글에서."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#1','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','「느티나무 밑 작은 돌」에서 시간을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],true,'{"seq":1,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「느티나무 밑 작은 돌」에서 시간을 나타내는 말은 어느 것인가요?","options":[{"t":"어느 날 아침","correct":true},{"t":"느티나무 밑","mis":"K1-2-u4-X04"},{"t":"작은 돌","mis":"K1-2-u4-X04"}],"explanation":["「어느 날 아침」은 언제인지 알려 줘요.","「느티나무 밑」은 어디, 「작은 돌」은 무엇이에요.","「언제?」에 답이 되는 말."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"},"variant_rule":{"alt":[{"stem":"「달님과 우물」에서 시간을 나타내는 말은 어느 것인가요?","options":[{"t":"이튿날 아침","correct":true},{"t":"우물 속","mis":"K1-2-u4-X04"},{"t":"물 한 바가지","mis":"K1-2-u4-X04"}],"explanation":["「이튿날 아침」은 언제인지 알려 줘요.","「우물 속」은 어디, 「물 한 바가지」는 무엇이에요.","「언제?」에 답이 되는 말."],"asset":{"type":"passage","lines":["옛날 옛적에 마을에 오래된 우물이 있었다.","어느 날 밤, 달님이 우물 속에 비쳤다.","아이가 \"달님이 빠졌어요!\" 하고 소리쳤다.","이튿날 아침, 할머니가 우물에서 물을 길어 올렸다.","물 한 바가지에 달님은 보이지 않았다.","할머니는 \"달님은 하늘에 잘 있단다.\" 하고 웃으셨다.","아이는 마음속으로 ''그래도 밤에 다시 봐야지.'' 하고 생각했다."],"title":"「달님과 우물」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#2','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',1,'mc','auto','「느티나무 밑 작은 돌」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「느티나무 밑 작은 돌」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"나그네가 돌 위에 앉아 쉬었다","correct":true},{"t":"할아버지가 노래를 불렀다","mis":"K1-2-u4-X05"},{"t":"돌 옆에 꽃밭이 생겼다","mis":"K1-2-u4-X05"}],"explanation":["「어느 날 아침」 나그네가 쉰 일이 먼저예요.","노래는 「저녁」, 꽃밭은 「이듬해 봄」이에요.","때를 알려 주는 말을 따라가요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#3','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',1,'mc','auto','큰따옴표 “ ”는 무엇을 나타낼 때 쓰나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":3,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"큰따옴표 “ ”는 무엇을 나타낼 때 쓰나요?","options":[{"t":"소리 내어 한 말","correct":true},{"t":"마음속으로 한 말","mis":"K1-2-u4-X06"},{"t":"글의 제목","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말에 큰따옴표를 써요.","마음속 말에는 작은따옴표를 써요.","입으로 낸 말인지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#4','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',1,'mc','auto','작은따옴표 ‘ ’는 무엇을 나타낼 때 쓰나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":4,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"작은따옴표 ‘ ’는 무엇을 나타낼 때 쓰나요?","options":[{"t":"마음속으로 혼자 한 말","correct":true},{"t":"소리 내어 한 말","mis":"K1-2-u4-X06"},{"t":"때를 알려 주는 말","mis":"K1-2-u4-X07"}],"explanation":["마음속으로 한 말에 작은따옴표를 써요.","소리 내어 한 말에는 큰따옴표예요.","가슴속에서 한 말인지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#5','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'match','auto','「느티나무 밑 작은 돌」에서 때와 그때 있었던 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"「느티나무 밑 작은 돌」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"어느 날 아침","r":"나그네가 돌 위에서 쉬었다"},{"l":"낮","r":"아이들이 들꽃을 올려놓았다"},{"l":"저녁","r":"할아버지가 노래를 불렀다"}],"mis":"K1-2-u4-X05","explanation":["아침에 나그네가 쉬었어요.","낮에 아이들이, 저녁에 할아버지가 왔어요.","때를 알려 주는 말 옆을 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"},"variant_rule":{"alt":[{"stem":"「달님과 우물」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"어느 날 밤","r":"달님이 우물에 비쳤다"},{"l":"이튿날 아침","r":"할머니가 물을 길어 올렸다"}],"explanation":["밤에 달님이 비쳤어요.","이튿날 아침에 할머니가 물을 길었어요.","때를 알려 주는 말 옆을 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 마을에 오래된 우물이 있었다.","어느 날 밤, 달님이 우물 속에 비쳤다.","아이가 \"달님이 빠졌어요!\" 하고 소리쳤다.","이튿날 아침, 할머니가 우물에서 물을 길어 올렸다.","물 한 바가지에 달님은 보이지 않았다.","할머니는 \"달님은 하늘에 잘 있단다.\" 하고 웃으셨다.","아이는 마음속으로 ''그래도 밤에 다시 봐야지.'' 하고 생각했다."],"title":"「달님과 우물」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#6','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'mc','auto','「느티나무 밑 작은 돌」에서 가장 나중에 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":6,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「느티나무 밑 작은 돌」에서 가장 나중에 있었던 일은 무엇인가요?","options":[{"t":"돌 옆에 작은 꽃밭이 생겼다","correct":true},{"t":"아이들이 들꽃을 올려놓았다","mis":"K1-2-u4-X05"},{"t":"나그네가 돌 위에서 쉬었다","mis":"K1-2-u4-X05"}],"explanation":["「이듬해 봄」이 가장 나중이에요.","들꽃은 낮, 나그네는 아침이에요.","이듬해는 다음 해예요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#7','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',2,'mc','auto','「느티나무 밑 작은 돌」에서 돌이 마음속으로 한 말은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"「느티나무 밑 작은 돌」에서 돌이 마음속으로 한 말은 어느 것인가요?","options":[{"t":"나도 쓸모가 있구나.","correct":true},{"t":"고마운 돌이구나.","mis":"K1-2-u4-X06"},{"t":"나도 힘을 보태야지.","mis":"K1-2-u4-X02"}],"explanation":["돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했어요.","「고마운 돌이구나」는 나그네가 소리 내어 한 말이에요.","작은따옴표 안을 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#8','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C3',2,'ox','auto','「고마운 돌이구나.」처럼 소리 내어 한 말에는 큰따옴표를 써요.',ARRAY['K1-2-u4-X06']::text[],true,'{"seq":8,"concept":"K1-2-u4-C3","difficulty":2,"kind":"ox","stem":"「고마운 돌이구나.」처럼 소리 내어 한 말에는 큰따옴표를 써요.","answer":"O","reason_options":[{"t":"입으로 소리 내어 한 말이니까","correct":true},{"t":"돌에게 한 말이니까","mis":"K1-2-u4-X06"}],"mis":"K1-2-u4-X06","explanation":["소리 내어 한 말에는 큰따옴표예요.","누구에게 했는지가 아니라 소리를 냈는지가 기준이에요.","입을 떠올려요."],"variant_rule":{"alt":[{"stem":"마음속으로 혼자 한 말에는 작은따옴표를 써요.","answer":"O","reason_options":[{"t":"소리 내지 않고 생각한 말이니까","correct":true},{"t":"짧은 말이니까","mis":"K1-2-u4-X06"}],"explanation":["마음속 말에는 작은따옴표예요.","길이가 아니라 소리를 냈는지가 기준이에요.","가슴을 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#9','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',2,'mc','auto','「느티나무 밑 작은 돌」에서 돌 옆에 꽃밭이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「느티나무 밑 작은 돌」에서 돌 옆에 꽃밭이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"아이들이 돌 위에 들꽃을 올려놓았기 때문에","correct":true},{"t":"돌이 아주 컸기 때문에","mis":"K1-2-u4-X02"},{"t":"나그네가 꽃을 심었기 때문에","mis":"K1-2-u4-X02"}],"explanation":["들꽃을 올려놓은 일이 꽃밭으로 이어졌어요.","돌이 크다거나 나그네가 심었다는 말은 글에 없어요.","때만 따라가지 말고 무슨 일이 있었는지도 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_basic#10','kor',1,2,'u4','L06','g1_2_kor_u4_L06_basic','lesson_basic','K1-2-u4-C2',3,'error','auto','「느티나무 밑 작은 돌」에서 시간을 나타내는 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#1','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',2,'mc','auto','「달님과 우물」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":1,"concept":"K1-2-u4-C2","difficulty":2,"kind":"mc","stem":"「달님과 우물」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"달님이 우물 속에 비쳤다","correct":true},{"t":"할머니가 물을 길어 올렸다","mis":"K1-2-u4-X05"},{"t":"아이가 밤에 다시 보기로 했다","mis":"K1-2-u4-X05"}],"explanation":["「어느 날 밤」 달님이 비친 일이 먼저예요.","물을 길은 일은 이튿날 아침이에요.","때를 알려 주는 말을 따라가요."],"asset":{"type":"passage","lines":["옛날 옛적에 마을에 오래된 우물이 있었다.","어느 날 밤, 달님이 우물 속에 비쳤다.","아이가 \"달님이 빠졌어요!\" 하고 소리쳤다.","이튿날 아침, 할머니가 우물에서 물을 길어 올렸다.","물 한 바가지에 달님은 보이지 않았다.","할머니는 \"달님은 하늘에 잘 있단다.\" 하고 웃으셨다.","아이는 마음속으로 ''그래도 밤에 다시 봐야지.'' 하고 생각했다."],"title":"「달님과 우물」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#2','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',2,'mc','auto','「달님과 우물」에서 아이가 소리 내어 한 말은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"「달님과 우물」에서 아이가 소리 내어 한 말은 어느 것인가요?","options":[{"t":"달님이 빠졌어요!","correct":true},{"t":"그래도 밤에 다시 봐야지.","mis":"K1-2-u4-X06"},{"t":"달님은 하늘에 잘 있단다.","mis":"K1-2-u4-X02"}],"explanation":["아이가 \"달님이 빠졌어요!\" 하고 소리쳤어요.","「다시 봐야지」는 마음속 말, 「하늘에 잘 있단다」는 할머니 말이에요.","큰따옴표 안에서 아이가 한 말을 찾아요."],"asset":{"type":"passage","lines":["옛날 옛적에 마을에 오래된 우물이 있었다.","어느 날 밤, 달님이 우물 속에 비쳤다.","아이가 \"달님이 빠졌어요!\" 하고 소리쳤다.","이튿날 아침, 할머니가 우물에서 물을 길어 올렸다.","물 한 바가지에 달님은 보이지 않았다.","할머니는 \"달님은 하늘에 잘 있단다.\" 하고 웃으셨다.","아이는 마음속으로 ''그래도 밤에 다시 봐야지.'' 하고 생각했다."],"title":"「달님과 우물」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#3','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'mc','auto','「달님과 우물」에서 할머니가 물을 길어 올린 때와, 그때 있었던 일을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u4-X05','K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「달님과 우물」에서 할머니가 물을 길어 올린 때와, 그때 있었던 일을 바르게 말한 것은 어느 것인가요?","options":[{"t":"이튿날 아침 — 바가지에 달님이 보이지 않았다","correct":true},{"t":"어느 날 밤 — 달님이 바가지에 담겼다","mis":"K1-2-u4-X05"},{"t":"이튿날 아침 — 달님이 하늘로 날아갔다","mis":"K1-2-u4-X02"}],"explanation":["이튿날 아침에 물을 길었고 달님은 보이지 않았어요.","밤이 아니고, 달님이 날아간 일은 글에 없어요.","때와 일을 함께 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 마을에 오래된 우물이 있었다.","어느 날 밤, 달님이 우물 속에 비쳤다.","아이가 \"달님이 빠졌어요!\" 하고 소리쳤다.","이튿날 아침, 할머니가 우물에서 물을 길어 올렸다.","물 한 바가지에 달님은 보이지 않았다.","할머니는 \"달님은 하늘에 잘 있단다.\" 하고 웃으셨다.","아이는 마음속으로 ''그래도 밤에 다시 봐야지.'' 하고 생각했다."],"title":"「달님과 우물」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#4','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',3,'error','auto','「달님과 우물」에서 일이 일어난 차례를 늘어놓았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#5','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',3,'mc','auto','다음 가운데 따옴표를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],true,'{"seq":5,"concept":"K1-2-u4-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 따옴표를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","correct":true},{"t":"돌은 마음속으로 \"나도 쓸모가 있구나.\" 하고 생각했다.","mis":"K1-2-u4-X06"},{"t":"돌은 마음속으로 나도 쓸모가 있구나.'' 하고 생각했다.","mis":"K1-2-u4-X07"}],"explanation":["마음속 말에는 작은따옴표를 열고 닫아요.","큰따옴표를 쓰면 소리 낸 말이 되고, 한쪽만 쓰면 안 돼요.","두 짝을 함께 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 따옴표를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"\"고마운 돌이구나.\" 나그네가 말했다.","correct":true},{"t":"''고마운 돌이구나.'' 나그네가 말했다.","mis":"K1-2-u4-X06"},{"t":"고마운 돌이구나.\" 나그네가 말했다.","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말에는 큰따옴표를 열고 닫아요.","작은따옴표를 쓰면 마음속 말이 되고, 한쪽만 쓰면 안 돼요.","두 짝을 함께."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#6','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',3,'match','auto','말과 그에 알맞은 따옴표를 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C3","difficulty":3,"kind":"match","stem":"말과 그에 알맞은 따옴표를 선으로 이어 보세요.","pairs":[{"l":"물을 주면 잘 자랄 거야. (소리 내어 한 말)","r":"큰따옴표 “ ”"},{"l":"나도 힘을 보태야지. (마음속으로 한 말)","r":"작은따옴표 ‘ ’"}],"mis":"K1-2-u4-X06","explanation":["소리 내어 한 말은 큰따옴표예요.","마음속 말은 작은따옴표예요.","입과 가슴을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#7','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',3,'ox','auto','따옴표는 글자 칸의 위쪽에 붙여 써요.',ARRAY['K1-2-u4-X07']::text[],false,'{"seq":7,"concept":"K1-2-u4-C3","difficulty":3,"kind":"ox","stem":"따옴표는 글자 칸의 위쪽에 붙여 써요.","answer":"O","reason_options":[{"t":"따옴표는 작은 짝이라 칸 위쪽에 붙여 써야 보기 좋으니까","correct":true},{"t":"따옴표는 어디에 써도 상관없으니까","mis":"K1-2-u4-X07"}],"mis":"K1-2-u4-X07","explanation":["칸 위쪽에 붙여 써요.","아무 데나 쓰면 말의 시작과 끝이 안 보여요.","따라 쓸 때 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#8','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',4,'sa','auto','「느티나무 밑 작은 돌」에서 꽃밭이 생긴 때를 알려 주는 말을 글에서 찾아 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u4-C2","difficulty":4,"kind":"sa","stem":"「느티나무 밑 작은 돌」에서 꽃밭이 생긴 때를 알려 주는 말을 글에서 찾아 쓰세요.","answer":["이듬해 봄","이듬해","이듬해 봄에"],"explanation":["「이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다」예요.","이듬해는 다음 해라는 뜻이에요.","마지막 줄 맨 앞을 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"},"variant_rule":{"alt":[{"stem":"「느티나무 밑 작은 돌」에서 할아버지가 노래를 부른 때를 알려 주는 말을 글에서 찾아 쓰세요.","answer":["저녁","저녁이 되자","저녁에"],"explanation":["「저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다」예요.","「언제?」에 답이 되는 말이에요.","그 문장 맨 앞을 봐요."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#9','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C2',4,'essay','teacher','「느티나무 밑 작은 돌」에서 돌이 「나도 쓸모가 있구나」 하고 생각한 까닭을 글에 있는 일을 들어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":4,"kind":"essay","stem":"「느티나무 밑 작은 돌」에서 돌이 「나도 쓸모가 있구나」 하고 생각한 까닭을 글에 있는 일을 들어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 나그네가 쉬어 가고 아이들이 꽃을 올려놓고 할아버지가 기대어 노래를 불렀기 때문이다. — 글에 있는 일 하나 이상을 까닭으로 들었으면 맞아요.","scoring_points":["글에 있는 일을 까닭으로 들었는가","「때문에」처럼 까닭 꼴인가","한 문장인가"]},"explanation":["때만 따라가지 말고 무슨 일이 있었는지 봐요.","세 사람이 돌을 찾아왔어요.","「~했기 때문에」."],"asset":{"type":"passage","lines":["옛날 옛적에 느티나무 밑에 작은 돌 하나가 있었다.","어느 날 아침, 나그네가 돌 위에 앉아 쉬었다.","\"고마운 돌이구나.\" 나그네가 말했다.","낮이 되자, 아이들이 돌 위에 들꽃을 올려놓았다.","저녁이 되자, 할아버지가 돌에 기대어 노래를 불렀다.","돌은 마음속으로 ''나도 쓸모가 있구나.'' 하고 생각했다.","이듬해 봄, 돌 옆에 작은 꽃밭이 생겼다."],"title":"「느티나무 밑 작은 돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L06_challenge#10','kor',1,2,'u4','L06','g1_2_kor_u4_L06_challenge','lesson_challenge','K1-2-u4-C3',4,'essay','teacher','친구가 「우산을 같이 쓰자.」 하고 소리 내어 말했고, 나는 마음속으로 「고맙다.」 하고 생각했어요. 두 말을 따옴표를 알맞게 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C3","difficulty":4,"kind":"essay","stem":"친구가 「우산을 같이 쓰자.」 하고 소리 내어 말했고, 나는 마음속으로 「고맙다.」 하고 생각했어요. 두 말을 따옴표를 알맞게 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 친구가 \"우산을 같이 쓰자.\" 하고 말했다. 나는 마음속으로 ''고맙다.'' 하고 생각했다. — 소리 낸 말에 큰따옴표, 마음속 말에 작은따옴표가 열리고 닫혔으면 맞아요.","scoring_points":["소리 낸 말에 큰따옴표인가","마음속 말에 작은따옴표인가","따옴표가 열리고 닫혔는가"]},"explanation":["입으로 낸 말은 큰따옴표예요.","마음속 말은 작은따옴표예요.","두 짝을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#1','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','「구름 위 우체부 토리」에 나오는 인물이 아닌 것은 어느 것인가요?',ARRAY['K1-2-u4-X03']::text[],true,'{"seq":1,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「구름 위 우체부 토리」에 나오는 인물이 아닌 것은 어느 것인가요?","options":[{"t":"마을 어부들","correct":true},{"t":"토리","mis":"K1-2-u4-X03"},{"t":"우체국장 할머니","mis":"K1-2-u4-X03"}],"explanation":["토리, 우체국장 할머니, 마을 아이들이 나와요.","어부들은 장면 카드에 없어요.","카드 네 장에서 이름을 찾아요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"},"variant_rule":{"alt":[{"stem":"「고장 난 로봇 삐삐」에 나오는 인물이 아닌 것은 어느 것인가요?","options":[{"t":"우체국장 할머니","correct":true},{"t":"삐삐","mis":"K1-2-u4-X03"},{"t":"다온","mis":"K1-2-u4-X03"}],"explanation":["삐삐와 다온이가 나와요.","우체국장 할머니는 다른 만화 영화 인물이에요.","카드 네 장에서 이름을 찾아요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#2','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','「구름 위 우체부 토리」에서 토리가 저녁에 한 일은 무엇인가요?',ARRAY['K1-2-u4-X05','K1-2-u4-X02']::text[],false,'{"seq":2,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「구름 위 우체부 토리」에서 토리가 저녁에 한 일은 무엇인가요?","options":[{"t":"젖은 편지를 날개로 감싸 말렸다","correct":true},{"t":"편지 자루를 받았다","mis":"K1-2-u4-X05"},{"t":"아이들에게 손을 흔들었다","mis":"K1-2-u4-X02"}],"explanation":["③ 저녁 카드에 편지를 말린 일이 있어요.","편지 자루는 아침에 받았고, 손을 흔든 것은 아이들이에요.","「저녁」 카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#3','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','「구름 위 우체부 토리」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":3,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「구름 위 우체부 토리」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"토리가 편지 자루를 받았다","correct":true},{"t":"토리가 산을 넘었다","mis":"K1-2-u4-X05"},{"t":"아이들이 편지를 받았다","mis":"K1-2-u4-X05"}],"explanation":["① 아침 카드가 가장 먼저예요.","산을 넘은 일은 낮, 아이들이 받은 일은 밤이에요.","카드 번호와 때를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#4','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',1,'mc','auto','만화 영화를 볼 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X08']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"만화 영화를 볼 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 나오고 무엇을 했는지","correct":true},{"t":"화면이 얼마나 큰지","mis":"K1-2-u4-X08"},{"t":"글자가 몇 개 나오는지","mis":"K1-2-u4-X08"}],"explanation":["인물과 인물이 한 일을 살펴요.","화면 크기나 글자 수는 이야기와 상관없어요.","이야기책을 볼 때와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#5','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'match','auto','「구름 위 우체부 토리」에서 때와 그때 있었던 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u4-C4","difficulty":2,"kind":"match","stem":"「구름 위 우체부 토리」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"아침","r":"편지 자루를 받았다"},{"l":"낮","r":"높은 산을 넘었다"},{"l":"밤","r":"아이들이 손을 흔들었다"}],"mis":"K1-2-u4-X05","explanation":["아침에 편지 자루를 받았어요.","낮에 산을 넘고, 밤에 아이들이 손을 흔들었어요.","카드마다 때가 적혀 있어요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"},"variant_rule":{"alt":[{"stem":"「고장 난 로봇 삐삐」에서 때와 그때 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"아침","r":"삐삐가 바퀴 빠진 채 서 있었다"},{"l":"낮","r":"다온이가 바퀴를 끼워 주었다"},{"l":"저녁","r":"삐삐가 다온이를 태우고 돌았다"}],"explanation":["아침에 삐삐는 바퀴가 빠져 있었어요.","낮에 다온이가 고쳐 주고, 저녁에 함께 돌았어요.","카드마다 때가 적혀 있어요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#6','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','「구름 위 우체부 토리」에서 가장 나중에 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「구름 위 우체부 토리」에서 가장 나중에 있었던 일은 무엇인가요?","options":[{"t":"아이들이 편지를 받고 손을 흔들었다","correct":true},{"t":"토리가 젖은 편지를 말렸다","mis":"K1-2-u4-X05"},{"t":"토리가 편지 자루를 받았다","mis":"K1-2-u4-X05"}],"explanation":["④ 밤 카드가 마지막이에요.","편지 말리기는 저녁, 편지 자루는 아침이에요.","카드 번호를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#7','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','있었던 일을 정리할 때 꼭 넣을 것을 모은 것은 어느 것인가요?',ARRAY['K1-2-u4-X08','K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"있었던 일을 정리할 때 꼭 넣을 것을 모은 것은 어느 것인가요?","options":[{"t":"언제 · 누가 · 무엇을 했는지","correct":true},{"t":"화면 색깔 · 글자 수","mis":"K1-2-u4-X08"},{"t":"내가 마음대로 정한 일","mis":"K1-2-u4-X02"}],"explanation":["언제·누가·무엇을이 들어가요.","화면 색깔은 상관없고, 마음대로 정한 일은 이야기에 없는 일이에요.","세 손가락으로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#8','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'ox','auto','「구름 위 우체부 토리」에서 토리는 낮에 바다를 건넜어요.',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":8,"concept":"K1-2-u4-C4","difficulty":2,"kind":"ox","stem":"「구름 위 우체부 토리」에서 토리는 낮에 바다를 건넜어요.","answer":"X","reason_options":[{"t":"② 낮 카드에는 높은 산을 넘었다고 되어 있으니까","correct":true},{"t":"토리는 새라서 바다도 건널 수 있으니까","mis":"K1-2-u4-X02"}],"mis":"K1-2-u4-X02","explanation":["낮에 토리는 산을 넘었어요.","새라면 그랬을 거라는 짐작은 카드에 없는 일이에요.","카드에 적힌 대로."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_basic#9','kor',1,2,'u4','L08','g1_2_kor_u4_L08_basic','lesson_basic','K1-2-u4-C4',2,'mc','auto','「고장 난 로봇 삐삐」에서 다온이가 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":9,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「고장 난 로봇 삐삐」에서 다온이가 한 일은 무엇인가요?","options":[{"t":"삐삐의 바퀴를 찾아 끼워 주었다","correct":true},{"t":"삐삐를 공원에 두고 갔다","mis":"K1-2-u4-X02"},{"t":"삐삐의 불빛을 고쳐 주었다","mis":"K1-2-u4-X02"}],"explanation":["② 낮 카드에 바퀴를 끼워 준 일이 있어요.","두고 간 일이나 불빛을 고친 일은 카드에 없어요.","다온이가 나오는 카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
