INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#1','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',2,'mc','auto','「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":1,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"삐삐가 바퀴가 빠진 채 서 있었다","correct":true},{"t":"삐삐가 다온이를 태우고 돌았다","mis":"K1-2-u4-X05"},{"t":"다온이가 바퀴를 끼워 주었다","mis":"K1-2-u4-X05"}],"explanation":["① 아침 카드가 먼저예요.","태우고 돈 것은 저녁, 바퀴를 끼운 것은 낮이에요.","카드 번호를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
