INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#3','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'mc','auto','「구름 위 우체부 토리」에서 토리가 편지를 날개로 감싼 까닭은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":3,"concept":"K1-2-u4-C4","difficulty":3,"kind":"mc","stem":"「구름 위 우체부 토리」에서 토리가 편지를 날개로 감싼 까닭은 무엇인가요?","options":[{"t":"비가 내려 편지가 젖어서","correct":true},{"t":"날개가 추워서","mis":"K1-2-u4-X02"},{"t":"아이들이 시켜서","mis":"K1-2-u4-X02"}],"explanation":["③ 저녁 카드에 「비가 내려」가 있어요.","날개가 춥다거나 아이들이 시켰다는 말은 없어요.","때만 보지 말고 왜 그랬는지도 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#4','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'error','auto','만화 영화를 볼 때 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#5','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'mc','auto','「고장 난 로봇 삐삐」를 「언제 · 누가 · 무엇을」이 모두 들어가게 정리한 문장은 어느 것인가요?',ARRAY['K1-2-u4-X09']::text[],true,'{"seq":5,"concept":"K1-2-u4-C4","difficulty":3,"kind":"mc","stem":"「고장 난 로봇 삐삐」를 「언제 · 누가 · 무엇을」이 모두 들어가게 정리한 문장은 어느 것인가요?","options":[{"t":"낮에 다온이가 삐삐의 바퀴를 끼워 주었다","correct":true},{"t":"다온이가 바퀴를 끼워 주었다","mis":"K1-2-u4-X09"},{"t":"낮에 바퀴를 끼웠다","mis":"K1-2-u4-X09"}],"explanation":["낮에(언제) 다온이가(누가) 바퀴를 끼워 주었다(무엇을)예요.","하나는 「언제」가, 하나는 「누가」가 빠졌어요.","세 손가락으로 세어요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"},"variant_rule":{"alt":[{"stem":"「구름 위 우체부 토리」를 「언제 · 누가 · 무엇을」이 모두 들어가게 정리한 문장은 어느 것인가요?","options":[{"t":"밤에 아이들이 편지를 받고 손을 흔들었다","correct":true},{"t":"아이들이 편지를 받고 손을 흔들었다","mis":"K1-2-u4-X09"},{"t":"밤에 편지를 받고 손을 흔들었다","mis":"K1-2-u4-X09"}],"explanation":["밤에(언제) 아이들이(누가) 손을 흔들었다(무엇을)예요.","하나는 「언제」가, 하나는 「누가」가 빠졌어요.","세 손가락."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#6','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'match','auto','「고장 난 로봇 삐삐」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C4","difficulty":3,"kind":"match","stem":"「고장 난 로봇 삐삐」에서 인물과 그 인물이 한 일을 선으로 이어 보세요.","pairs":[{"l":"삐삐","r":"다온이를 태우고 공원을 돌았다"},{"l":"다온","r":"삐삐의 바퀴를 끼워 주었다"}],"mis":"K1-2-u4-X02","explanation":["삐삐는 저녁에 다온이를 태웠어요.","다온이는 낮에 바퀴를 끼워 주었어요.","인물마다 한 일이 달라요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#7','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',3,'ox','auto','「고장 난 로봇 삐삐」에서 삐삐가 불빛을 깜빡인 것은 다온이에게 인사한 것이라고 카드에 적혀 있어요.',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C4","difficulty":3,"kind":"ox","stem":"「고장 난 로봇 삐삐」에서 삐삐가 불빛을 깜빡인 것은 다온이에게 인사한 것이라고 카드에 적혀 있어요.","answer":"O","reason_options":[{"t":"④ 밤 카드에 「불빛을 깜빡이며 인사했다」고 되어 있으니까","correct":true},{"t":"로봇은 늘 불빛을 깜빡이니까","mis":"K1-2-u4-X02"}],"mis":"K1-2-u4-X02","explanation":["카드에 적힌 대로 인사한 거예요.","로봇이 늘 그런다는 짐작이 아니라 카드를 봐요.","④ 카드를 다시 읽어요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#8','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',4,'sa','auto','「구름 위 우체부 토리」에서 토리가 산을 넘은 때를 카드에서 찾아 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u4-C4","difficulty":4,"kind":"sa","stem":"「구름 위 우체부 토리」에서 토리가 산을 넘은 때를 카드에서 찾아 쓰세요.","answer":["낮","낮에"],"explanation":["② 낮 — 토리는 산을 넘었어요.","카드 번호 옆에 때가 적혀 있어요.","「언제?」"],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"},"variant_rule":{"alt":[{"stem":"「고장 난 로봇 삐삐」에서 삐삐가 불빛으로 인사한 때를 카드에서 찾아 쓰세요.","answer":["밤","밤에"],"explanation":["④ 밤 — 불빛을 깜빡이며 인사했어요.","카드 번호 옆에 때가 적혀 있어요.","「언제?」"],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#9','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',4,'essay','teacher','「구름 위 우체부 토리」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「구름 위 우체부 토리」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.","answer_guide":{"answer":"예: 아침에 토리가 편지 자루를 받았다. 낮에 토리가 산을 넘었다. 저녁에 토리가 젖은 편지를 말렸다. 밤에 아이들이 편지를 받았다. — 때 순서가 맞고 문장마다 언제·누가·무엇을이 있으면 맞아요.","scoring_points":["차례가 아침→낮→저녁→밤인가","문장마다 언제·누가·무엇을이 있는가","카드에 없는 일을 넣지 않았는가"]},"explanation":["카드 순서대로 써요.","언제·누가·무엇을 세 가지씩.","없는 일은 넣지 않아요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L08_challenge#10','kor',1,2,'u4','L08','g1_2_kor_u4_L08_challenge','lesson_challenge','K1-2-u4-C4',4,'essay','teacher','「고장 난 로봇 삐삐」에서 삐삐가 다온이를 태우고 공원을 돈 까닭을 앞 카드의 일을 들어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「고장 난 로봇 삐삐」에서 삐삐가 다온이를 태우고 공원을 돈 까닭을 앞 카드의 일을 들어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 다온이가 빠진 바퀴를 찾아 끼워 주었기 때문이다. — ② 낮 카드의 일을 까닭으로 들었으면 맞아요.","scoring_points":["앞 카드의 일을 까닭으로 들었는가","「때문에」처럼 까닭 꼴인가","한 문장인가"]},"explanation":["앞에 있었던 일이 까닭이 돼요.","다온이가 바퀴를 끼워 주었어요.","「~했기 때문에」."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#1','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','이야기를 보다가 마음이 뭉클해지는 것을 무엇이라고 하나요?',ARRAY['K1-2-u4-X04','K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"이야기를 보다가 마음이 뭉클해지는 것을 무엇이라고 하나요?","options":[{"t":"감동","correct":true},{"t":"차례","mis":"K1-2-u4-X04"},{"t":"인물","mis":"K1-2-u4-X03"}],"explanation":["마음이 뭉클해지는 것이 감동이에요.","차례는 일의 순서, 인물은 나오는 사람이에요.","「뭉클」을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#2','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','감동적인 장면을 말할 때 함께 말해야 하는 것은 무엇인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X11']::text[],false,'{"seq":2,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"감동적인 장면을 말할 때 함께 말해야 하는 것은 무엇인가요?","options":[{"t":"왜 그렇게 느꼈는지 까닭","correct":true},{"t":"만화의 길이","mis":"K1-2-u4-X13"},{"t":"친구가 고른 장면","mis":"K1-2-u4-X11"}],"explanation":["까닭을 함께 말해요.","만화 길이는 상관없고, 친구 장면은 내 마음이 아니에요.","「왜냐하면」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#3','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','까닭을 함께 말한 친구는 누구인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X10']::text[],true,'{"seq":3,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"까닭을 함께 말한 친구는 누구인가요?","options":[{"t":"지후","correct":true},{"t":"다온","mis":"K1-2-u4-X13"},{"t":"둘 다 아니에요","mis":"K1-2-u4-X10"}],"explanation":["지후는 「편지를 지키려고 애쓰는 게 뭉클해서」라고 까닭을 말했어요.","다온이는 색깔이 많아서라고 했는데, 그것은 인물이 한 일이 아니에요.","까닭이 인물에게서 왔는지 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"어느 장면이 마음에 남았나요?"},{"who":"지후","text":"토리가 젖은 편지를 날개로 말린 장면이요. 편지를 지키려고 애쓰는 게 뭉클했어요."}]},"variant_rule":{"alt":[{"stem":"까닭을 인물이 한 일에서 찾지 못한 친구는 누구인가요?","options":[{"t":"다온","correct":true},{"t":"지후","mis":"K1-2-u4-X13"},{"t":"둘 다 잘 말했어요","mis":"K1-2-u4-X13"}],"explanation":["다온이는 「색깔이 많아서」라고 했어요.","색깔 수는 마음이 움직인 까닭이 되지 못해요.","인물이 무엇을 했는지에서 찾아요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"어느 장면이 마음에 남았나요?"},{"who":"다온","text":"그 만화 색깔이 많아서 감동이었어요."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#4','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',1,'mc','auto','친구가 나와 다른 장면을 골랐을 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":4,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"친구가 나와 다른 장면을 골랐을 때 알맞은 것은 어느 것인가요?","options":[{"t":"그럴 수 있다고 생각하고 까닭을 들어 본다","correct":true},{"t":"틀렸다고 고쳐 준다","mis":"K1-2-u4-X12"},{"t":"내 장면으로 바꾸라고 한다","mis":"K1-2-u4-X12"}],"explanation":["사람마다 마음이 움직이는 곳이 달라요.","틀렸다고 하거나 바꾸게 하면 안 돼요.","까닭을 물어봐요."],"asset":{"type":"speech","turns":[{"who":"지후","text":"나는 할머니가 손을 흔들며 버스를 탄 장면이 제일 좋았어."},{"who":"다온","text":"그건 틀렸어. 우산 장면이 감동이지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#5','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','다온이가 잘못한 점은 무엇인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"다온이가 잘못한 점은 무엇인가요?","options":[{"t":"친구가 고른 장면을 틀렸다고 말했다","correct":true},{"t":"장면을 고르지 않았다","mis":"K1-2-u4-X10"},{"t":"까닭을 너무 길게 말했다","mis":"K1-2-u4-X10"}],"explanation":["감동은 사람마다 달라서 틀린 것이 없어요.","다온이는 장면을 골랐고, 까닭이 길어서 문제가 아니에요.","「그건 틀렸어」를 봐요."],"asset":{"type":"speech","turns":[{"who":"지후","text":"나는 할머니가 손을 흔들며 버스를 탄 장면이 제일 좋았어."},{"who":"다온","text":"그건 틀렸어. 우산 장면이 감동이지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#6','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','민솔이가 잘못한 점은 무엇인가요?',ARRAY['K1-2-u4-X10']::text[],true,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"민솔이가 잘못한 점은 무엇인가요?","options":[{"t":"서아의 느낌을 그대로 따라 말했다","correct":true},{"t":"장면을 두 개 골랐다","mis":"K1-2-u4-X10"},{"t":"너무 큰 소리로 말했다","mis":"K1-2-u4-X10"}],"explanation":["「나도 그 장면. 서아가 그렇다니까」는 내 느낌이 아니에요.","장면은 하나였고 목소리는 상관없어요.","서아가 되물은 까닭을 봐요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"나는 우산을 씌워 드린 장면이 감동이었어."},{"who":"민솔","text":"나도 그 장면. 서아가 그렇다니까."},{"who":"서아","text":"네 마음은 어디에서 움직였는데?"}]},"variant_rule":{"alt":[{"stem":"서아가 민솔이에게 「네 마음은 어디에서 움직였는데?」 하고 물은 까닭은 무엇인가요?","options":[{"t":"민솔이가 자기 느낌이 아니라 서아 느낌을 따라 말해서","correct":true},{"t":"민솔이가 장면을 안 골라서","mis":"K1-2-u4-X10"},{"t":"민솔이가 틀린 장면을 골라서","mis":"K1-2-u4-X12"}],"explanation":["따라 말하면 그것은 친구의 느낌이에요.","장면은 골랐고, 틀린 장면은 없어요.","내 마음은 내 말로."],"asset":{"type":"speech","turns":[{"who":"서아","text":"나는 우산을 씌워 드린 장면이 감동이었어."},{"who":"민솔","text":"나도 그 장면. 서아가 그렇다니까."},{"who":"서아","text":"네 마음은 어디에서 움직였는데?"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#7','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'match','auto','장면과 그 장면이 감동인 까닭을 선으로 이어 보세요. (「작은 우산」)','{}'::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":2,"kind":"match","stem":"장면과 그 장면이 감동인 까닭을 선으로 이어 보세요. (「작은 우산」)","pairs":[{"l":"지후가 우산을 씌워 드린 장면","r":"비를 맞으면서도 할머니를 먼저 생각해서"},{"l":"할머니가 손을 흔든 장면","r":"고마운 마음이 느껴져서"}],"mis":"K1-2-u4-X10","explanation":["나린이와 도윤이가 말한 까닭이에요.","장면마다 까닭이 달라요.","말풍선을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「작은 우산」에서 어느 장면이 가장 마음에 남았나요?"},{"who":"나린","text":"지후가 우산을 씌워 드린 장면이요. 비를 맞으면서도 할머니를 먼저 생각해서요."},{"who":"도윤","text":"나는 할머니가 손을 흔든 장면이요. 고마운 마음이 느껴졌어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#8','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'ox','auto','같은 이야기를 보아도 감동적인 장면은 사람마다 다를 수 있어요.',ARRAY['K1-2-u4-X12']::text[],true,'{"seq":8,"concept":"K1-2-u4-C5","difficulty":2,"kind":"ox","stem":"같은 이야기를 보아도 감동적인 장면은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 겪은 일이 달라서 마음이 움직이는 곳도 다르니까","correct":true},{"t":"감동적인 장면은 하나로 정해져 있으니까","mis":"K1-2-u4-X12"}],"mis":"K1-2-u4-X12","explanation":["감동은 사람마다 달라요.","정해진 답이 있는 것이 아니에요.","나린이와 도윤이가 다른 장면을 골랐어요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「작은 우산」에서 어느 장면이 가장 마음에 남았나요?"},{"who":"나린","text":"지후가 우산을 씌워 드린 장면이요. 비를 맞으면서도 할머니를 먼저 생각해서요."},{"who":"도윤","text":"나는 할머니가 손을 흔든 장면이요. 고마운 마음이 느껴졌어요."}]},"variant_rule":{"alt":[{"stem":"친구와 내가 고른 장면이 다르면 둘 중 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"감동은 사람마다 달라서 틀린 것이 없으니까","correct":true},{"t":"선생님이 정답을 알려 주시니까","mis":"K1-2-u4-X12"}],"explanation":["틀린 것이 없어요.","정답을 가리는 일이 아니에요.","까닭을 들어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#9','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',2,'mc','auto','「재미있었다」 한마디만 말하면 어떤 점이 아쉬운가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"「재미있었다」 한마디만 말하면 어떤 점이 아쉬운가요?","options":[{"t":"무엇이 어떻게 좋았는지 알 수 없다","correct":true},{"t":"말이 너무 길다","mis":"K1-2-u4-X10"},{"t":"장면을 두 개 말한 것이 된다","mis":"K1-2-u4-X10"}],"explanation":["한마디만으로는 마음이 안 보여요.","길어서가 아니라 짧아서 안 보여요.","선생님이 되물은 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이야기를 보고 어땠나요?"},{"who":"민솔","text":"재미있었어요."},{"who":"선생님","text":"무엇이 어떻게 재미있었나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_basic#10','kor',1,2,'u4','L10','g1_2_kor_u4_L10_basic','lesson_basic','K1-2-u4-C5',3,'error','auto','감동을 느낀 까닭을 찾을 때 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#1','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',2,'mc','auto','도윤이가 고른 장면과 그 까닭을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K1-2-u4-X10','K1-2-u4-X13']::text[],false,'{"seq":1,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"도윤이가 고른 장면과 그 까닭을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"할머니가 손을 흔든 장면 — 고마운 마음이 느껴져서","correct":true},{"t":"우산을 씌워 드린 장면 — 고마운 마음이 느껴져서","mis":"K1-2-u4-X10"},{"t":"할머니가 손을 흔든 장면 — 색이 예뻐서","mis":"K1-2-u4-X13"}],"explanation":["도윤이는 손을 흔든 장면을 고마움 때문에 골랐어요.","우산 장면은 나린이 것, 색은 까닭이 아니에요.","말풍선을 봐요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「작은 우산」에서 어느 장면이 가장 마음에 남았나요?"},{"who":"나린","text":"지후가 우산을 씌워 드린 장면이요. 비를 맞으면서도 할머니를 먼저 생각해서요."},{"who":"도윤","text":"나는 할머니가 손을 흔든 장면이요. 고마운 마음이 느껴졌어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#2','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',2,'mc','auto','민솔이가 자기 느낌을 말하려면 어떻게 해야 할까요?',ARRAY['K1-2-u4-X11']::text[],false,'{"seq":2,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"민솔이가 자기 느낌을 말하려면 어떻게 해야 할까요?","options":[{"t":"내 마음이 움직인 장면을 내가 느낀 까닭과 함께 말한다","correct":true},{"t":"서아보다 더 크게 같은 말을 한다","mis":"K1-2-u4-X11"},{"t":"서아가 고른 장면을 외워서 말한다","mis":"K1-2-u4-X11"}],"explanation":["내 장면, 내 까닭으로 말해요.","같은 말을 크게 하거나 외워서 하면 여전히 서아의 느낌이에요.","「내 마음은 어디에서?」"],"asset":{"type":"speech","turns":[{"who":"서아","text":"나는 우산을 씌워 드린 장면이 감동이었어."},{"who":"민솔","text":"나도 그 장면. 서아가 그렇다니까."},{"who":"서아","text":"네 마음은 어디에서 움직였는데?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#3','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'mc','auto','감동의 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X10']::text[],true,'{"seq":3,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"감동의 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"형이 멈춘 종이배를 밀어 주어서 마음이 따뜻했다","correct":true},{"t":"종이배 이야기가 짧아서 좋았다","mis":"K1-2-u4-X13"},{"t":"그냥 감동이었다","mis":"K1-2-u4-X10"}],"explanation":["인물이 한 일에서 까닭을 찾았어요.","길이는 까닭이 아니고, 「그냥」은 까닭이 없는 거예요.","형이 무엇을 했는지."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 감동의 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"할머니가 비 맞는 지후를 보고 고맙다고 웃어 주셔서 마음이 따뜻했다","correct":true},{"t":"우산 그림이 파란색이라서 좋았다","mis":"K1-2-u4-X13"},{"t":"친구가 좋다고 해서 좋았다","mis":"K1-2-u4-X11"}],"explanation":["인물이 한 말에서 까닭을 찾았어요.","색깔은 까닭이 아니고, 친구 말을 따르면 내 느낌이 아니에요.","할머니가 무엇을 했는지."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#4','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'error','auto','친구가 나와 다른 장면을 골랐을 때 할 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#5','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'mc','auto','「눈물이 났다」 뒤에 붙이면 좋은 말은 어느 것인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X11']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":3,"kind":"mc","stem":"「눈물이 났다」 뒤에 붙이면 좋은 말은 어느 것인가요?","options":[{"t":"토리가 비를 맞으면서도 편지를 지켰기 때문이에요","correct":true},{"t":"만화가 길었기 때문이에요","mis":"K1-2-u4-X13"},{"t":"친구도 울었기 때문이에요","mis":"K1-2-u4-X11"}],"explanation":["인물이 한 일을 까닭으로 붙여요.","길이는 까닭이 아니고, 친구 때문은 내 느낌이 아니에요.","「왜냐하면」 뒤에 인물."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#6','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'match','auto','말하는 모습과 고칠 점을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C5","difficulty":3,"kind":"match","stem":"말하는 모습과 고칠 점을 선으로 이어 보세요.","pairs":[{"l":"「재미있었어요」 한마디로 끝냄","r":"무엇이 어떻게 좋았는지 까닭 붙이기"},{"l":"친구 느낌을 그대로 따라 말함","r":"내 마음이 움직인 곳을 내 말로 말하기"},{"l":"다른 장면 고른 친구에게 틀렸다고 함","r":"그럴 수 있다고 여기고 까닭 들어 보기"}],"mis":"K1-2-u4-X10","explanation":["한마디는 까닭을 붙여요.","따라 말하기는 내 말로, 틀렸다는 말은 존중으로 바꿔요.","세 가지 고칠 점."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#7','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',3,'ox','auto','감동을 느낀 까닭은 인물이 한 말이나 행동에서 찾을 수 있어요.',ARRAY['K1-2-u4-X13']::text[],false,'{"seq":7,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"감동을 느낀 까닭은 인물이 한 말이나 행동에서 찾을 수 있어요.","answer":"O","reason_options":[{"t":"마음을 움직인 것은 인물이 무엇을 했는지이기 때문에","correct":true},{"t":"그림이 예쁘면 저절로 감동이 되니까","mis":"K1-2-u4-X13"}],"mis":"K1-2-u4-X13","explanation":["까닭은 인물에게서 찾아요.","그림 솜씨나 색은 까닭이 아니에요.","인물이 한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#8','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'sa','auto','빈칸에 들어갈 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#9','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','「작은 우산」에서 가장 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「작은 우산」에서 가장 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 할머니가 \"고맙다, 꼬마야.\" 하고 웃으신 장면이 남았다. 지후가 한 일을 할머니가 알아주셔서 나도 기뻤다. — 장면 하나와 인물에게서 찾은 까닭이 있으면 맞아요(어느 장면이든 좋아요).","scoring_points":["장면이 하나인가","까닭이 인물의 말·행동에서 왔는가","내 말로 썼는가"]},"explanation":["장면 하나, 까닭 하나.","까닭은 인물이 한 일에서.","어느 장면이든 좋아요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L10_challenge#10','kor',1,2,'u4','L10','g1_2_kor_u4_L10_challenge','lesson_challenge','K1-2-u4-C5',4,'essay','teacher','민솔이가 「재미있었어요」라고만 말했어요. 민솔이가 되어 「작은 우산」에서 무엇이 어떻게 좋았는지 까닭을 넣어 한 문장으로 다시 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"민솔이가 「재미있었어요」라고만 말했어요. 민솔이가 되어 「작은 우산」에서 무엇이 어떻게 좋았는지 까닭을 넣어 한 문장으로 다시 말해 보세요.","answer_guide":{"answer":"예: 지후가 자기 옷이 젖는 것도 잊고 할머니께 우산을 씌워 드려서 마음이 따뜻했어요. — 무엇이(인물이 한 일)·어떻게(느낌)가 들어 있으면 맞아요.","scoring_points":["인물이 한 일이 있는가","느낌이 있는가","한 문장인가"]},"explanation":["무엇이 어떻게 좋았는지 말해요.","인물이 한 일을 넣어요.","한마디로 끝내지 않기."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"이야기를 보고 어땠나요?"},{"who":"민솔","text":"재미있었어요."},{"who":"선생님","text":"무엇이 어떻게 재미있었나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#1','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12','K1-2-u4-X14']::text[],false,'{"seq":1,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 마음이 움직인 장면","correct":true},{"t":"친구가 고른 장면","mis":"K1-2-u4-X12"},{"t":"가장 그리기 쉬운 장면","mis":"K1-2-u4-X14"}],"explanation":["내 마음이 움직인 장면을 골라요.","친구 장면이나 쉬운 장면은 내 감동이 아니에요.","마음이 뭉클했던 곳."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#2','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','그림에 꼭 드러나야 하는 것은 무엇인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":2,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림에 꼭 드러나야 하는 것은 무엇인가요?","options":[{"t":"인물과 인물이 한 일","correct":true},{"t":"예쁜 테두리 무늬","mis":"K1-2-u4-X14"},{"t":"그린 사람 이름","mis":"K1-2-u4-X15"}],"explanation":["누가 무엇을 하는 장면인지 보여야 해요.","테두리나 이름으로는 어떤 장면인지 몰라요.","그림만 보고도 알 수 있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#3','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','감동한 장면을 그릴 때 더 중요한 것은 무엇인가요?',ARRAY['K1-2-u4-X14']::text[],false,'{"seq":3,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"감동한 장면을 그릴 때 더 중요한 것은 무엇인가요?","options":[{"t":"감동받은 부분이 드러나게 그리기","correct":true},{"t":"되도록 예쁘게 그리기","mis":"K1-2-u4-X14"},{"t":"색을 많이 쓰기","mis":"K1-2-u4-X14"}],"explanation":["감동이 드러나는 것이 먼저예요.","미술 시간이 아니라 감동을 나누는 시간이에요.","무슨 장면인지 보이게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#4','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',1,'mc','auto','그림 옆 빈 곳에 쓰면 좋은 것은 무엇인가요?',ARRAY['K1-2-u4-X15']::text[],false,'{"seq":4,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림 옆 빈 곳에 쓰면 좋은 것은 무엇인가요?","options":[{"t":"어떤 장면을 왜 그렸는지","correct":true},{"t":"그림을 그린 시간","mis":"K1-2-u4-X15"},{"t":"내 키와 나이","mis":"K1-2-u4-X15"}],"explanation":["장면과 까닭을 적어 두면 좋아요.","시간이나 키는 장면과 상관없어요.","「왜 이 장면?」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#5','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'mc','auto','세 걸음을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K1-2-u4-X05']::text[],true,'{"seq":5,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"세 걸음을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"말하기 → 그리기 → 나누기","correct":true},{"t":"그리기 → 말하기 → 나누기","mis":"K1-2-u4-X05"},{"t":"나누기 → 그리기 → 말하기","mis":"K1-2-u4-X05"}],"explanation":["먼저 말하고, 그리고, 나누어요.","차례가 바뀌면 무엇을 그릴지 정하기 전에 그리게 돼요.","말·그림·나눔."],"variant_rule":{"alt":[{"stem":"세 걸음 가운데 가장 먼저 할 일은 무엇인가요?","options":[{"t":"어느 장면이 감동이었는지 말하기","correct":true},{"t":"바로 색칠부터 하기","mis":"K1-2-u4-X14"},{"t":"친구 그림 보러 가기","mis":"K1-2-u4-X16"}],"explanation":["먼저 말해 보고 그려요.","색칠부터 하면 무엇을 그릴지 흐려지고, 친구 그림은 나중이에요.","첫걸음은 말하기."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#6','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'mc','auto','어떤 장면인지 알 수 있는 그림은 어느 것인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],true,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"어떤 장면인지 알 수 있는 그림은 어느 것인가요?","options":[{"t":"지후가 할머니께 우산을 씌워 드리는 그림","correct":true},{"t":"테두리만 알록달록 꾸민 그림","mis":"K1-2-u4-X14"},{"t":"우산만 크게 그린 그림","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보여요.","테두리나 물건만으로는 장면을 몰라요.","누가 무엇을."],"asset":{"type":"scene","icon":"☔👵🧒","text":"지후가 할머니께 우산을 씌워 드리는 장면"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 어떤 장면인지 알 수 있는 그림은 어느 것인가요?","options":[{"t":"형이 나뭇가지로 종이배를 밀어 주는 그림","correct":true},{"t":"개울만 파랗게 칠한 그림","mis":"K1-2-u4-X15"},{"t":"테두리를 별로 꾸민 그림","mis":"K1-2-u4-X14"}],"explanation":["인물과 한 일이 보여요.","개울이나 테두리만으로는 장면을 몰라요.","누가 무엇을."],"asset":{"type":"scene","icon":"🌊⛵🧒","text":"형이 나뭇가지로 종이배를 밀어 주는 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#7','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'mc','auto','친구 그림을 볼 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X16','K1-2-u4-X12']::text[],false,'{"seq":7,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"친구 그림을 볼 때 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 장면을 골랐는지 견주어 보며 존중한다","correct":true},{"t":"누가 제일 잘 그렸는지 고른다","mis":"K1-2-u4-X16"},{"t":"내 것과 다르면 틀렸다고 한다","mis":"K1-2-u4-X12"}],"explanation":["견주어 보고 존중하며 봐요.","잘 그린 사람을 뽑는 활동이 아니에요.","장면과 까닭을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#8','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'ox','auto','친구가 나와 아주 다른 장면을 그렸으면 왜 그 장면을 골랐는지 물어보면 좋아요.',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":8,"concept":"K1-2-u4-C6","difficulty":2,"kind":"ox","stem":"친구가 나와 아주 다른 장면을 그렸으면 왜 그 장면을 골랐는지 물어보면 좋아요.","answer":"O","reason_options":[{"t":"사람마다 마음이 움직인 곳이 달라서 물어보면 더 재미있으니까","correct":true},{"t":"친구가 틀렸는지 확인해야 하니까","mis":"K1-2-u4-X12"}],"mis":"K1-2-u4-X12","explanation":["왜 그 장면인지 물어봐요.","틀렸는지 확인하는 게 아니에요.","민솔이가 서아에게 물은 말."],"asset":{"type":"speech","turns":[{"who":"서아","text":"나는 비둘기가 날아가는 장면을 그렸어."},{"who":"민솔","text":"나는 빵을 주는 장면인데. 너는 왜 그 장면을 골랐어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#9','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',2,'match','auto','말한 사람과 그 말이 어떤 말인지 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C6","difficulty":2,"kind":"match","stem":"말한 사람과 그 말이 어떤 말인지 선으로 이어 보세요.","pairs":[{"l":"나린","r":"어떤 장면을 왜 그렸는지 소개했다"},{"l":"도윤","r":"그림의 좋은 점을 짚어 주었다"},{"l":"다온","r":"색을 흉보았다"}],"mis":"K1-2-u4-X16","explanation":["나린이는 장면과 까닭을 소개했어요.","도윤이는 좋은 점을 짚었고, 다온이 말은 흉이에요.","말풍선을 봐요."],"asset":{"type":"speech","turns":[{"who":"나린","text":"나는 지후가 할머니께 우산을 씌워 드리는 장면을 그렸어요. 비를 맞으면서도 할머니를 생각한 마음이 뭉클해서요."},{"who":"도윤","text":"우산 아래 두 사람이 웃는 모습이 잘 보여서 좋았어."},{"who":"다온","text":"우산 색이 이상해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_basic#10','kor',1,2,'u4','L12','g1_2_kor_u4_L12_basic','lesson_basic','K1-2-u4-C6',3,'error','auto','그림에 드러나면 좋은 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#1','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',2,'mc','auto','다온이의 말이 소개나 감상으로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K1-2-u4-X16']::text[],false,'{"seq":1,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"다온이의 말이 소개나 감상으로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"장면이나 감동이 아니라 색만 흉보았기 때문에","correct":true},{"t":"너무 짧게 말했기 때문에","mis":"K1-2-u4-X16"},{"t":"나린이 그림을 보지 않았기 때문에","mis":"K1-2-u4-X16"}],"explanation":["꾸미기만 따지는 말은 감상이 아니에요.","짧아서가 아니라 흉이라서 문제예요.","「우산 색이 이상해」."],"asset":{"type":"speech","turns":[{"who":"나린","text":"나는 지후가 할머니께 우산을 씌워 드리는 장면을 그렸어요. 비를 맞으면서도 할머니를 생각한 마음이 뭉클해서요."},{"who":"도윤","text":"우산 아래 두 사람이 웃는 모습이 잘 보여서 좋았어."},{"who":"다온","text":"우산 색이 이상해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#2','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',2,'mc','auto','도윤이가 나린이의 그림을 보고 한 말이 좋은 까닭은 무엇인가요?',ARRAY['K1-2-u4-X16','K1-2-u4-X14']::text[],false,'{"seq":2,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"도윤이가 나린이의 그림을 보고 한 말이 좋은 까닭은 무엇인가요?","options":[{"t":"그림에서 장면이 잘 보인다는 점을 짚어 주어서","correct":true},{"t":"나린이보다 자기가 잘 그렸다고 해서","mis":"K1-2-u4-X16"},{"t":"색이 많다고 칭찬해서","mis":"K1-2-u4-X14"}],"explanation":["「두 사람이 웃는 모습이 잘 보여서」라고 짚었어요.","견주거나 색만 보는 말이 아니에요.","장면이 보이는지."],"asset":{"type":"speech","turns":[{"who":"나린","text":"나는 지후가 할머니께 우산을 씌워 드리는 장면을 그렸어요. 비를 맞으면서도 할머니를 생각한 마음이 뭉클해서요."},{"who":"도윤","text":"우산 아래 두 사람이 웃는 모습이 잘 보여서 좋았어."},{"who":"다온","text":"우산 색이 이상해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#3','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'mc','auto','「작은 우산」을 그림으로 나타낼 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X15']::text[],true,'{"seq":3,"concept":"K1-2-u4-C6","difficulty":3,"kind":"mc","stem":"「작은 우산」을 그림으로 나타낼 때 알맞은 것은 어느 것인가요?","options":[{"t":"우산 아래 지후와 할머니가 나란히 선 한 장면","correct":true},{"t":"지후 집부터 정류장까지 가는 길 전부","mis":"K1-2-u4-X15"},{"t":"비 오는 하늘만","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보이는 한 장면이에요.","길 전부나 하늘만으로는 장면이 안 보여요.","누가 무엇을."],"asset":{"type":"scene","icon":"☔👵🧒","text":"지후가 할머니께 우산을 씌워 드리는 장면"},"variant_rule":{"alt":[{"stem":"「구름 위 우체부 토리」를 그림으로 나타낼 때 알맞은 것은 어느 것인가요?","options":[{"t":"토리가 젖은 편지를 날개로 감싸는 한 장면","correct":true},{"t":"산과 구름만 크게","mis":"K1-2-u4-X15"},{"t":"네 장면을 한 칸에 다 넣기","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보이는 한 장면이에요.","배경만이나 전부 넣기는 안 돼요.","누가 무엇을."],"asset":{"type":"scene","icon":"🐦💌🌧️","text":"토리가 젖은 편지를 날개로 감싸는 장면"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#4','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'error','auto','그림을 소개하는 말에 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#5','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'mc','auto','그림에 시간을 다 써서 감동한 까닭을 적지 못했어요. 어떻게 하면 좋을까요?',ARRAY['K1-2-u4-X14','K1-2-u4-X11']::text[],false,'{"seq":5,"concept":"K1-2-u4-C6","difficulty":3,"kind":"mc","stem":"그림에 시간을 다 써서 감동한 까닭을 적지 못했어요. 어떻게 하면 좋을까요?","options":[{"t":"그림은 장면이 보일 만큼만 그리고 까닭 쓸 시간을 남긴다","correct":true},{"t":"까닭은 안 써도 되니 그림만 더 꾸민다","mis":"K1-2-u4-X14"},{"t":"친구 까닭을 베껴 쓴다","mis":"K1-2-u4-X11"}],"explanation":["장면이 보이면 충분해요.","꾸미기만 하거나 베끼면 내 감동이 안 남아요.","시간을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#6','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'match','auto','세 걸음과 그때 할 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":3,"kind":"match","stem":"세 걸음과 그때 할 일을 선으로 이어 보세요.","pairs":[{"l":"말하기","r":"어느 장면이 왜 감동이었는지 말한다"},{"l":"그리기","r":"인물과 한 일이 보이게 한 장면을 그린다"},{"l":"나누기","r":"무엇을 왜 그렸는지 소개하고 친구 그림을 본다"}],"mis":"K1-2-u4-X14","explanation":["말하고, 그리고, 나누어요.","걸음마다 할 일이 달라요.","세 걸음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#7','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',3,'ox','auto','그림 옆에 「어떤 장면을 왜 그렸는지」 적어 두면 보는 사람이 내 감동을 더 잘 알 수 있어요.',ARRAY['K1-2-u4-X14']::text[],false,'{"seq":7,"concept":"K1-2-u4-C6","difficulty":3,"kind":"ox","stem":"그림 옆에 「어떤 장면을 왜 그렸는지」 적어 두면 보는 사람이 내 감동을 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"그림만으로 알기 어려운 까닭까지 전해지니까","correct":true},{"t":"글이 있어야 그림이 예뻐 보이니까","mis":"K1-2-u4-X14"}],"mis":"K1-2-u4-X14","explanation":["장면과 까닭을 적어 두면 좋아요.","예뻐 보이려는 게 아니에요.","감동을 전하려고."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#8','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'sa','auto','빈칸에 들어갈 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#9','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'essay','teacher','「공원의 비둘기」에서 마음이 움직인 장면 하나를 골라, 그림을 소개하는 말을 두 문장으로 쓰세요. (무엇을 그렸는지 · 왜 그 장면인지)','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C6","difficulty":4,"kind":"essay","stem":"「공원의 비둘기」에서 마음이 움직인 장면 하나를 골라, 그림을 소개하는 말을 두 문장으로 쓰세요. (무엇을 그렸는지 · 왜 그 장면인지)","answer_guide":{"answer":"예: 서아가 비둘기에게 빵을 주는 장면을 그렸어요. 배고픈 비둘기를 그냥 보내지 않아서 마음이 따뜻했기 때문이에요. — 그린 장면(인물과 한 일)과 까닭이 있으면 맞아요.","scoring_points":["인물과 한 일이 있는 한 장면인가","왜 그 장면인지가 있는가","두 문장인가"]},"explanation":["무엇을 그렸는지부터.","왜 그 장면인지까지.","어느 장면이든 좋아요."],"asset":{"type":"scene","icon":"🕊️🍞👧","text":"서아가 비둘기에게 빵을 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_L12_challenge#10','kor',1,2,'u4','L12','g1_2_kor_u4_L12_challenge','lesson_challenge','K1-2-u4-C6',4,'essay','teacher','다온이가 나린이 그림을 보고 「우산 색이 이상해」라고 했어요. 다온이가 되어 나린이 그림의 좋은 점을 짚어 주는 말을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C6","difficulty":4,"kind":"essay","stem":"다온이가 나린이 그림을 보고 「우산 색이 이상해」라고 했어요. 다온이가 되어 나린이 그림의 좋은 점을 짚어 주는 말을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 할머니와 지후가 우산 아래에서 웃는 모습이 잘 보여서 좋았어. — 장면이 보인다는 점이나 감동이 드러난 점을 짚었으면 맞아요.","scoring_points":["흉이 아니라 좋은 점인가","장면·감동과 관련된 말인가","나린이에게 하는 말로 썼는가"]},"explanation":["좋은 점을 짚어 말해요.","색칠 흉은 감상이 아니에요.","도윤이의 말을 본보기로."],"asset":{"type":"speech","turns":[{"who":"나린","text":"나는 지후가 할머니께 우산을 씌워 드리는 장면을 그렸어요. 비를 맞으면서도 할머니를 생각한 마음이 뭉클해서요."},{"who":"도윤","text":"우산 아래 두 사람이 웃는 모습이 잘 보여서 좋았어."},{"who":"다온","text":"우산 색이 이상해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#1','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',1,'mc','auto','「씨앗 심은 날」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」에 나오는 인물은 누구인가요?","options":[{"t":"나린, 도윤, 선생님","correct":true},{"t":"나린, 도윤, 엄마","mis":"K1-2-u4-X03"},{"t":"서아, 지후, 선생님","mis":"K1-2-u4-X03"}],"explanation":["「나」는 나린이고 도윤이와 선생님이 나와요.","엄마·서아·지후는 없어요.","이름을 찾아요."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#2','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',1,'mc','auto','「씨앗 심은 날」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"지난 월요일 아침","correct":true},{"t":"화단에","mis":"K1-2-u4-X04"},{"t":"씨앗을","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이에요.","화단에는 어디, 씨앗을은 무엇이에요.","때."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#3','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',1,'mc','auto','소리 내어 한 말에 쓰는 따옴표는 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":3,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"소리 내어 한 말에 쓰는 따옴표는 어느 것인가요?","options":[{"t":"큰따옴표 “ ”","correct":true},{"t":"작은따옴표 ‘ ’","mis":"K1-2-u4-X06"},{"t":"따옴표를 쓰지 않는다","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말은 큰따옴표예요.","작은따옴표는 마음속 말이에요.","입."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#4','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',1,'mc','auto','「구름 위 우체부 토리」에 나오지 않는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「구름 위 우체부 토리」에 나오지 않는 인물은 누구인가요?","options":[{"t":"어부들","correct":true},{"t":"토리","mis":"K1-2-u4-X03"},{"t":"마을 아이들","mis":"K1-2-u4-X03"}],"explanation":["토리·할머니·아이들이 나와요.","어부들은 없어요.","카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#5','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',1,'mc','auto','감동적인 장면을 말할 때 함께 말할 것은 무엇인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X11']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"감동적인 장면을 말할 때 함께 말할 것은 무엇인가요?","options":[{"t":"왜 그렇게 느꼈는지 까닭","correct":true},{"t":"그림이 몇 장인지","mis":"K1-2-u4-X13"},{"t":"친구가 고른 장면","mis":"K1-2-u4-X11"}],"explanation":["까닭을 함께 말해요.","그림 수나 친구 장면은 아니에요.","왜냐하면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#6','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C6',1,'mc','auto','감동한 장면 그림에 꼭 드러나야 하는 것은 무엇인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"감동한 장면 그림에 꼭 드러나야 하는 것은 무엇인가요?","options":[{"t":"인물과 인물이 한 일","correct":true},{"t":"예쁜 테두리","mis":"K1-2-u4-X14"},{"t":"그린 날짜","mis":"K1-2-u4-X15"}],"explanation":["누가 무엇을 하는지 보여야 해요.","테두리·날짜로는 몰라요.","그림만 보고도."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#7','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',1,'mc','auto','「씨앗 심은 날」에서 도윤이가 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「씨앗 심은 날」에서 도윤이가 한 일은 무엇인가요?","options":[{"t":"구멍을 파고 물을 주었다","correct":true},{"t":"씨앗을 나누어 주었다","mis":"K1-2-u4-X02"},{"t":"흙을 덮었다","mis":"K1-2-u4-X02"}],"explanation":["구멍 파기와 물 주기가 도윤이 일이에요.","씨앗은 선생님, 흙은 나린이에요.","도윤이 줄."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
