INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#9','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',2,'match','auto','「씨앗 심은 날」에서 때와 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"「씨앗 심은 날」에서 때와 일을 선으로 이어 보세요.","pairs":[{"l":"지난 월요일 아침","r":"화단에 나갔다"},{"l":"낮","r":"도윤이가 물을 주었다"}],"mis":"K1-2-u4-X05","explanation":["아침에 화단에 나갔어요.","낮에 물을 주었어요.","때 옆."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#10','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C1',2,'match','auto','「씨앗 심은 날」에서 인물과 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「씨앗 심은 날」에서 인물과 한 일을 선으로 이어 보세요.","pairs":[{"l":"나린","r":"흙을 덮었다"},{"l":"도윤","r":"물을 주었다"},{"l":"선생님","r":"씨앗을 나누어 주셨다"}],"mis":"K1-2-u4-X02","explanation":["나린이는 흙.","도윤이는 물, 선생님은 씨앗.","인물마다."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#11','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',2,'mc','auto','「구름 위 우체부 토리」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":11,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「구름 위 우체부 토리」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"편지 자루를 받았다","correct":true},{"t":"산을 넘었다","mis":"K1-2-u4-X05"},{"t":"아이들이 손을 흔들었다","mis":"K1-2-u4-X05"}],"explanation":["① 아침이 먼저예요.","산은 낮, 아이들은 밤.","카드 번호."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#12','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',2,'mc','auto','친구가 나와 다른 장면을 골랐을 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":12,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 장면을 골랐을 때 알맞은 것은 어느 것인가요?","options":[{"t":"그럴 수 있다고 생각하고 까닭을 들어 본다","correct":true},{"t":"틀렸다고 말해 준다","mis":"K1-2-u4-X12"},{"t":"내 장면으로 바꾸게 한다","mis":"K1-2-u4-X12"}],"explanation":["사람마다 달라요.","틀렸다고 하지 않아요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#13','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',2,'mc','auto','「씨앗 심은 날」에서 작은따옴표 안에 있는 말은 어느 것인가요?',ARRAY['K1-2-u4-X06']::text[],false,'{"seq":13,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"「씨앗 심은 날」에서 작은따옴표 안에 있는 말은 어느 것인가요?","options":[{"t":"빨리 싹이 났으면.","correct":true},{"t":"내가 구멍을 팔게.","mis":"K1-2-u4-X06"},{"t":"싹이 나면 함께 보자.","mis":"K1-2-u4-X06"}],"explanation":["나린이가 마음속으로 한 생각이에요.","나머지 둘은 소리 내어 한 말이라 큰따옴표예요.","가슴."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#14','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C6',2,'mc','auto','감동한 장면을 그림으로 나타내는 세 걸음을 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":14,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"감동한 장면을 그림으로 나타내는 세 걸음을 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"말하기 → 그리기 → 나누기","correct":true},{"t":"그리기 → 말하기 → 나누기","mis":"K1-2-u4-X05"},{"t":"나누기 → 말하기 → 그리기","mis":"K1-2-u4-X05"}],"explanation":["말하고, 그리고, 나누어요.","차례가 바뀌면 안 돼요.","세 걸음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#15','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',2,'ox','auto','「씨앗 심은 날」에서 도윤이가 물을 준 일은 우리 반이 화단에 나간 일보다 먼저 있었어요.',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"「씨앗 심은 날」에서 도윤이가 물을 준 일은 우리 반이 화단에 나간 일보다 먼저 있었어요.","answer":"X","reason_options":[{"t":"화단에 나간 일이 「지난 월요일 아침」 첫 줄이고 물은 「낮에」 주었으니까","correct":true},{"t":"물을 줘야 씨앗을 심으니까","mis":"K1-2-u4-X05"}],"mis":"K1-2-u4-X05","explanation":["화단에 나간 일이 먼저예요.","짐작이 아니라 때를 알려 주는 말로 정해요.","아침→낮."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#16','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',2,'mc','auto','민솔이가 잘못한 점은 무엇인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"민솔이가 잘못한 점은 무엇인가요?","options":[{"t":"서아의 느낌을 그대로 따라 말했다","correct":true},{"t":"장면을 두 개 골랐다","mis":"K1-2-u4-X10"},{"t":"너무 크게 말했다","mis":"K1-2-u4-X10"}],"explanation":["따라 말하면 내 느낌이 아니에요.","장면은 하나, 목소리는 상관없어요.","서아가 되물은 까닭."],"asset":{"type":"speech","turns":[{"who":"서아","text":"나는 우산을 씌워 드린 장면이 감동이었어."},{"who":"민솔","text":"나도 그 장면. 서아가 그렇다니까."},{"who":"서아","text":"네 마음은 어디에서 움직였는데?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
