INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#19','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',3,'ox','auto','감동의 까닭은 인물이 한 말이나 행동에서 찾을 수 있어요.',ARRAY['K1-2-u4-X13']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"감동의 까닭은 인물이 한 말이나 행동에서 찾을 수 있어요.","answer":"O","reason_options":[{"t":"마음을 움직인 것은 인물이 무엇을 했는지이니까","correct":true},{"t":"그림이 예쁘면 저절로 감동이니까","mis":"K1-2-u4-X13"}],"mis":"K1-2-u4-X13","explanation":["인물에게서 찾아요.","그림 솜씨는 까닭이 아니에요.","인물이 한 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#20','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C2',3,'mc','auto','「씨앗 심은 날」에서 나린이가 「빨리 싹이 났으면」 하고 생각한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":20,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「씨앗 심은 날」에서 나린이가 「빨리 싹이 났으면」 하고 생각한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"씨앗을 심고 물을 주었기 때문에","correct":true},{"t":"선생님께서 혼내셨기 때문에","mis":"K1-2-u4-X02"},{"t":"싹이 이미 났기 때문에","mis":"K1-2-u4-X02"}],"explanation":["심고 물을 준 뒤라 싹이 기다려져요.","혼난 일, 싹이 난 일은 없어요.","앞에 있었던 일."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#21','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C6',3,'error','auto','그림을 소개하는 말에 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#22','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C3',3,'mc','auto','따옴표를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":22,"concept":"K1-2-u4-C3","difficulty":3,"kind":"mc","stem":"따옴표를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","correct":true},{"t":"도윤이가 ''내가 구멍을 팔게.'' 하고 말했다.","mis":"K1-2-u4-X06"},{"t":"도윤이가 내가 구멍을 팔게.\" 하고 말했다.","mis":"K1-2-u4-X07"}],"explanation":["소리 낸 말은 큰따옴표를 열고 닫아요.","작은따옴표는 마음속 말, 한쪽만은 안 돼요.","두 짝."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#23','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C7',4,'sa','auto','그림을 보고 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#24','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C5',4,'essay','teacher','「씨앗 심은 날」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「씨앗 심은 날」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 도윤이가 먼저 나서서 구멍을 파 준 장면이 남았다. 친구를 도우려는 마음이 보여서 기분이 좋았다. — 장면 하나와 인물에게서 찾은 까닭이 있으면 맞아요.","scoring_points":["장면이 하나인가","까닭이 인물의 말·행동에서 왔는가","내 말로 썼는가"]},"explanation":["장면 하나, 까닭 하나.","인물이 한 일에서.","어느 장면이든."],"asset":{"type":"passage","lines":["지난 월요일 아침, 우리 반은 화단에 나갔다.","선생님께서 작은 씨앗을 한 알씩 나누어 주셨다.","도윤이가 \"내가 구멍을 팔게.\" 하고 말했다.","나는 씨앗을 넣고 흙을 살살 덮었다.","낮에 도윤이는 물뿌리개로 물을 주었다.","선생님께서 \"싹이 나면 함께 보자.\" 하고 말씀하셨다.","나는 마음속으로 ''빨리 싹이 났으면.'' 하고 생각했다."],"title":"「씨앗 심은 날」 — 나린이가 쓴 글(「나」는 나린)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_a#25','kor',1,2,'u4','','g1_2_kor_u4_review_a','unit_review','K1-2-u4-C4',4,'essay','teacher','「구름 위 우체부 토리」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「구름 위 우체부 토리」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.","answer_guide":{"answer":"예: 아침에 토리가 편지 자루를 받았다. 낮에 토리가 산을 넘었다. 저녁에 토리가 젖은 편지를 말렸다. 밤에 아이들이 편지를 받았다. — 차례가 맞고 문장마다 언제·누가·무엇을이 있으면 맞아요.","scoring_points":["차례가 아침→낮→저녁→밤인가","문장마다 언제·누가·무엇을이 있는가","카드에 없는 일을 넣지 않았는가"]},"explanation":["카드 순서대로.","세 가지씩.","없는 일은 빼요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#1','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',1,'mc','auto','「공원의 비둘기」에 나오는 사람은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「공원의 비둘기」에 나오는 사람은 누구인가요?","options":[{"t":"서아와 엄마","correct":true},{"t":"서아와 할머니","mis":"K1-2-u4-X03"},{"t":"나린이와 엄마","mis":"K1-2-u4-X03"}],"explanation":["서아와 엄마가 공원에 갔어요.","할머니·나린이는 없어요.","이름을 찾아요."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#2','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',1,'mc','auto','「공원의 비둘기」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「공원의 비둘기」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"토요일 아침","correct":true},{"t":"공원에","mis":"K1-2-u4-X04"},{"t":"빵 조각을","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이에요.","공원에는 어디, 빵 조각을은 무엇이에요.","때."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#3','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C3',1,'mc','auto','마음속으로 혼자 한 말에 쓰는 따옴표는 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":3,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"마음속으로 혼자 한 말에 쓰는 따옴표는 어느 것인가요?","options":[{"t":"작은따옴표 ‘ ’","correct":true},{"t":"큰따옴표 “ ”","mis":"K1-2-u4-X06"},{"t":"따옴표를 쓰지 않는다","mis":"K1-2-u4-X07"}],"explanation":["마음속 말은 작은따옴표예요.","큰따옴표는 소리 낸 말이에요.","가슴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#4','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',1,'mc','auto','「고장 난 로봇 삐삐」에 나오지 않는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「고장 난 로봇 삐삐」에 나오지 않는 인물은 누구인가요?","options":[{"t":"할머니","correct":true},{"t":"삐삐","mis":"K1-2-u4-X03"},{"t":"다온","mis":"K1-2-u4-X03"}],"explanation":["삐삐와 다온이가 나와요.","할머니는 없어요.","카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#5','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',1,'mc','auto','느낌을 말하는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u4-X11','K1-2-u4-X10']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"느낌을 말하는 알맞은 방법은 어느 것인가요?","options":[{"t":"내가 느낀 대로 까닭과 함께 말한다","correct":true},{"t":"친구 말을 그대로 따라 한다","mis":"K1-2-u4-X11"},{"t":"「재미있었다」 한마디만 한다","mis":"K1-2-u4-X10"}],"explanation":["내 느낌을 까닭과 함께.","따라 하거나 한마디는 안 돼요.","내 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#6','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C6',1,'mc','auto','그림을 그릴 때 더 중요한 것은 무엇인가요?',ARRAY['K1-2-u4-X14']::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림을 그릴 때 더 중요한 것은 무엇인가요?","options":[{"t":"감동받은 부분이 드러나게","correct":true},{"t":"되도록 예쁘게","mis":"K1-2-u4-X14"},{"t":"색을 많이","mis":"K1-2-u4-X14"}],"explanation":["드러남이 먼저예요.","미술 시간이 아니에요.","무슨 장면인지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#7','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',1,'mc','auto','「공원의 비둘기」에서 엄마가 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「공원의 비둘기」에서 엄마가 한 일은 무엇인가요?","options":[{"t":"빵 조각을 떼어 주었다","correct":true},{"t":"비둘기를 그렸다","mis":"K1-2-u4-X02"},{"t":"비둘기를 쫓았다","mis":"K1-2-u4-X02"}],"explanation":["엄마가 빵을 주셨어요.","그림은 서아, 쫓은 일은 없어요.","엄마 줄."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#8','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C7',1,'mc','auto','동작을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":8,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"동작을 나타내는 말은 어느 것인가요?","options":[{"t":"엽니다","correct":true},{"t":"문","mis":"K1-2-u4-X17"},{"t":"노랗다","mis":"K1-2-u4-X17"}],"explanation":["「엽니다」는 움직임이에요.","문은 이름, 노랗다는 색이에요.","몸으로 해 볼 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#9','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',2,'match','auto','「공원의 비둘기」에서 때와 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"「공원의 비둘기」에서 때와 일을 선으로 이어 보세요.","pairs":[{"l":"토요일 아침","r":"공원에 갔다"},{"l":"낮","r":"비둘기가 발 앞에 앉았다"},{"l":"저녁","r":"비둘기를 그렸다"}],"mis":"K1-2-u4-X05","explanation":["아침에 공원.","낮에 비둘기, 저녁에 그림.","때 옆."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#10','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',2,'match','auto','「공원의 비둘기」에서 인물과 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「공원의 비둘기」에서 인물과 한 일을 선으로 이어 보세요.","pairs":[{"l":"서아","r":"비둘기를 그렸다"},{"l":"엄마","r":"빵 조각을 주었다"},{"l":"비둘기","r":"빵을 먹고 날아갔다"}],"mis":"K1-2-u4-X02","explanation":["서아는 그림.","엄마는 빵, 비둘기는 날아갔어요.","인물마다."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#11','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',2,'mc','auto','「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":11,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일은 무엇인가요?","options":[{"t":"삐삐가 바퀴 빠진 채 서 있었다","correct":true},{"t":"다온이가 바퀴를 끼웠다","mis":"K1-2-u4-X05"},{"t":"삐삐가 불빛으로 인사했다","mis":"K1-2-u4-X05"}],"explanation":["① 아침이 먼저예요.","바퀴 끼우기는 낮, 인사는 밤.","카드 번호."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#12','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',2,'mc','auto','다온이가 잘못한 점은 무엇인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":12,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"다온이가 잘못한 점은 무엇인가요?","options":[{"t":"친구가 고른 장면을 틀렸다고 했다","correct":true},{"t":"장면을 안 골랐다","mis":"K1-2-u4-X10"},{"t":"까닭을 길게 말했다","mis":"K1-2-u4-X10"}],"explanation":["감동은 틀린 것이 없어요.","장면은 골랐어요.","「그건 틀렸어」."],"asset":{"type":"speech","turns":[{"who":"지후","text":"나는 할머니가 손을 흔들며 버스를 탄 장면이 제일 좋았어."},{"who":"다온","text":"그건 틀렸어. 우산 장면이 감동이지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
