INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#14','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C6',2,'mc','auto','어떤 장면인지 알 수 있는 그림은 어느 것인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":14,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"어떤 장면인지 알 수 있는 그림은 어느 것인가요?","options":[{"t":"서아가 비둘기에게 빵을 주는 그림","correct":true},{"t":"테두리만 꾸민 그림","mis":"K1-2-u4-X14"},{"t":"빵만 크게 그린 그림","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보여요.","테두리·물건만으로는 몰라요.","누가 무엇을."],"asset":{"type":"scene","icon":"🕊️🍞👧","text":"서아가 비둘기에게 빵을 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#15','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',2,'ox','auto','「공원의 비둘기」에서 서아가 비둘기를 그린 일은 공원에 간 일보다 나중에 있었어요.',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"「공원의 비둘기」에서 서아가 비둘기를 그린 일은 공원에 간 일보다 나중에 있었어요.","answer":"O","reason_options":[{"t":"공원은 「토요일 아침」, 그림은 「저녁에」니까","correct":true},{"t":"그림은 늘 마지막에 그리니까","mis":"K1-2-u4-X05"}],"mis":"K1-2-u4-X05","explanation":["아침이 먼저, 저녁이 나중이에요.","짐작이 아니라 때로 정해요.","아침→저녁."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#16','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',2,'mc','auto','까닭을 인물이 한 일에서 찾은 친구는 누구인가요?',ARRAY['K1-2-u4-X13','K1-2-u4-X10']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"까닭을 인물이 한 일에서 찾은 친구는 누구인가요?","options":[{"t":"지후","correct":true},{"t":"다온","mis":"K1-2-u4-X13"},{"t":"둘 다 아니에요","mis":"K1-2-u4-X10"}],"explanation":["지후는 「편지를 지키려고 애쓰는 게 뭉클해서」라고 했어요.","다온이는 색깔 수를 말했어요.","인물에게서."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"어느 장면이 마음에 남았나요?"},{"who":"지후","text":"토리가 젖은 편지를 날개로 말린 장면이요. 편지를 지키려고 애쓰는 게 뭉클했어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#17','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C1',3,'error','auto','「공원의 비둘기」에서 있었던 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#18','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',3,'error','auto','있었던 일을 정리할 때 넣을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#19','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',3,'ox','auto','만화의 색깔이 많다는 것은 감동의 까닭이 될 수 있어요.',ARRAY['K1-2-u4-X13']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"만화의 색깔이 많다는 것은 감동의 까닭이 될 수 있어요.","answer":"X","reason_options":[{"t":"마음이 움직인 까닭은 인물이 한 일에서 찾아야 하니까","correct":true},{"t":"색이 많으면 마음도 움직이니까","mis":"K1-2-u4-X13"}],"mis":"K1-2-u4-X13","explanation":["색깔 수는 까닭이 아니에요.","인물이 무엇을 했는지에서 찾아요.","다온이의 말을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#20','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C2',3,'mc','auto','「공원의 비둘기」에서 서아가 저녁에 비둘기를 그린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":20,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「공원의 비둘기」에서 서아가 저녁에 비둘기를 그린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"낮에 공원에서 비둘기를 만났기 때문에","correct":true},{"t":"엄마가 그리라고 시켰기 때문에","mis":"K1-2-u4-X02"},{"t":"비둘기를 집에 데려왔기 때문에","mis":"K1-2-u4-X02"}],"explanation":["낮의 만남이 저녁 그림으로 이어졌어요.","시킨 일, 데려온 일은 없어요.","앞에 있었던 일."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#21','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C6',3,'error','auto','친구 그림을 볼 때 할 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#22','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C3',3,'mc','auto','따옴표를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":22,"concept":"K1-2-u4-C3","difficulty":3,"kind":"mc","stem":"따옴표를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다.","correct":true},{"t":"서아는 마음속으로 \"또 만나고 싶다.\" 하고 생각했다.","mis":"K1-2-u4-X06"},{"t":"서아는 마음속으로 ''또 만나고 싶다. 하고 생각했다.","mis":"K1-2-u4-X07"}],"explanation":["마음속 말은 작은따옴표를 열고 닫아요.","큰따옴표는 소리 낸 말, 한쪽만은 안 돼요.","두 짝."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#23','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C7',4,'sa','auto','그림을 보고 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#24','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C5',4,'essay','teacher','「공원의 비둘기」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「공원의 비둘기」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 엄마가 빵 조각을 떼어 준 장면이 남았다. 배고픈 비둘기를 지나치지 않아서 마음이 따뜻했다. — 장면 하나와 인물에게서 찾은 까닭이 있으면 맞아요.","scoring_points":["장면이 하나인가","까닭이 인물의 말·행동에서 왔는가","내 말로 썼는가"]},"explanation":["장면 하나, 까닭 하나.","인물이 한 일에서.","어느 장면이든."],"asset":{"type":"passage","lines":["토요일 아침, 서아는 엄마와 공원에 갔다.","낮이 되자 비둘기 한 마리가 서아 발 앞에 앉았다.","서아는 \"배가 고픈가 봐.\" 하고 말했다.","엄마가 빵 조각을 조금 떼어 주셨다.","비둘기는 빵을 먹고 날아갔다.","저녁에 서아는 집에서 비둘기를 그렸다.","서아는 마음속으로 ''또 만나고 싶다.'' 하고 생각했다."],"title":"「공원의 비둘기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_b#25','kor',1,2,'u4','','g1_2_kor_u4_review_b','unit_review','K1-2-u4-C4',4,'essay','teacher','「고장 난 로봇 삐삐」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「고장 난 로봇 삐삐」에서 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 차례대로 세 문장 이상 쓰세요.","answer_guide":{"answer":"예: 아침에 삐삐가 바퀴 빠진 채 서 있었다. 낮에 다온이가 바퀴를 끼워 주었다. 저녁에 삐삐가 다온이를 태우고 공원을 돌았다. 밤에 삐삐가 불빛으로 인사했다. — 차례가 맞고 문장마다 언제·누가·무엇을이 있으면 맞아요.","scoring_points":["차례가 아침→낮→저녁→밤인가","문장마다 언제·누가·무엇을이 있는가","카드에 없는 일을 넣지 않았는가"]},"explanation":["카드 순서대로.","세 가지씩.","없는 일은 빼요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#1','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C1',1,'mc','auto','「작은 우산」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「작은 우산」에 나오는 인물은 누구인가요?","options":[{"t":"지후와 할머니","correct":true},{"t":"지후와 형","mis":"K1-2-u4-X03"},{"t":"민솔이와 할머니","mis":"K1-2-u4-X03"}],"explanation":["지후와 할머니가 정류장에서 만났어요.","형·민솔이는 없어요.","이름을 찾아요."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#2','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',1,'mc','auto','「작은 우산」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「작은 우산」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"비 오는 날 오후","correct":true},{"t":"버스 정류장에서","mis":"K1-2-u4-X04"},{"t":"우산을","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이에요.","정류장에서는 어디, 우산을은 무엇이에요.","때."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#3','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C3',1,'mc','auto','큰따옴표 “ ”는 언제 쓰나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":3,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"큰따옴표 “ ”는 언제 쓰나요?","options":[{"t":"소리 내어 한 말을 적을 때","correct":true},{"t":"마음속으로 한 말을 적을 때","mis":"K1-2-u4-X06"},{"t":"글의 제목을 적을 때","mis":"K1-2-u4-X07"}],"explanation":["소리 내어 한 말에 써요.","마음속 말은 작은따옴표예요.","입."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#4','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',1,'mc','auto','「구름 위 우체부 토리」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「구름 위 우체부 토리」에 나오는 인물은 누구인가요?","options":[{"t":"토리, 우체국장 할머니, 마을 아이들","correct":true},{"t":"토리, 다온, 어부들","mis":"K1-2-u4-X03"},{"t":"삐삐, 할머니, 아이들","mis":"K1-2-u4-X03"}],"explanation":["카드 네 장에 셋이 나와요.","다온·어부·삐삐는 없어요.","카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
