INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#11','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',2,'mc','auto','「구름 위 우체부 토리」에서 가장 나중에 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":11,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「구름 위 우체부 토리」에서 가장 나중에 있었던 일은 무엇인가요?","options":[{"t":"아이들이 편지를 받고 손을 흔들었다","correct":true},{"t":"젖은 편지를 말렸다","mis":"K1-2-u4-X05"},{"t":"편지 자루를 받았다","mis":"K1-2-u4-X05"}],"explanation":["④ 밤이 마지막이에요.","말리기는 저녁, 자루는 아침.","카드 번호."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#12','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',2,'mc','auto','같은 이야기를 보고 느낌이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12']::text[],false,'{"seq":12,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"같은 이야기를 보고 느낌이 다른 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"너는 왜 그 장면이 남았어?","correct":true},{"t":"그건 아니야, 이 장면이 맞아.","mis":"K1-2-u4-X12"},{"t":"나랑 똑같이 골라.","mis":"K1-2-u4-X12"}],"explanation":["까닭을 물어봐요.","고치거나 맞추게 하지 않아요.","존중."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#13','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C3',2,'mc','auto','「작은 우산」에서 작은따옴표 안에 있는 말은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":13,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"「작은 우산」에서 작은따옴표 안에 있는 말은 어느 것인가요?","options":[{"t":"그래도 참 잘했어.","correct":true},{"t":"고맙다, 꼬마야.","mis":"K1-2-u4-X06"},{"t":"옷이 조금 젖어 있었다.","mis":"K1-2-u4-X07"}],"explanation":["지후가 마음속으로 한 생각이에요.","「고맙다, 꼬마야」는 소리 낸 말이에요.","가슴."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#14','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C6',2,'mc','auto','어떤 장면인지 알 수 있는 그림은 어느 것인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":14,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"어떤 장면인지 알 수 있는 그림은 어느 것인가요?","options":[{"t":"지후가 할머니께 우산을 씌워 드리는 그림","correct":true},{"t":"테두리만 꾸민 그림","mis":"K1-2-u4-X14"},{"t":"비 오는 하늘만 그린 그림","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보여요.","테두리·하늘만으로는 몰라요.","누가 무엇을."],"asset":{"type":"scene","icon":"☔👵🧒","text":"지후가 할머니께 우산을 씌워 드리는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#15','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',2,'ox','auto','「작은 우산」에서 지후가 집에 온 일은 우산을 씌워 드린 일보다 먼저 있었어요.',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"「작은 우산」에서 지후가 집에 온 일은 우산을 씌워 드린 일보다 먼저 있었어요.","answer":"X","reason_options":[{"t":"우산은 「비 오는 날 오후」, 집은 「저녁에」니까","correct":true},{"t":"집에 가야 우산을 가져오니까","mis":"K1-2-u4-X05"}],"mis":"K1-2-u4-X05","explanation":["오후가 먼저, 저녁이 나중이에요.","짐작이 아니라 때로 정해요.","오후→저녁."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#16','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',2,'mc','auto','다온이의 까닭이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"다온이의 까닭이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"색깔 수는 마음이 움직인 까닭이 되지 못해서","correct":true},{"t":"말이 너무 짧아서","mis":"K1-2-u4-X10"},{"t":"장면을 말하지 않아서","mis":"K1-2-u4-X10"}],"explanation":["까닭은 인물이 한 일에서 찾아요.","짧아서가 아니에요.","색은 까닭이 아니에요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"어느 장면이 마음에 남았나요?"},{"who":"다온","text":"그 만화 색깔이 많아서 감동이었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
