INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#18','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',3,'error','auto','만화 영화를 볼 때 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#19','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',3,'ox','auto','친구가 고른 장면을 그대로 말하면 그것은 친구의 느낌이에요.',ARRAY['K1-2-u4-X11']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"친구가 고른 장면을 그대로 말하면 그것은 친구의 느낌이에요.","answer":"O","reason_options":[{"t":"내 마음이 움직인 곳을 내 말로 말해야 내 느낌이니까","correct":true},{"t":"친구 말은 늘 틀리니까","mis":"K1-2-u4-X11"}],"mis":"K1-2-u4-X11","explanation":["따라 말하면 내 느낌이 아니에요.","친구가 틀려서가 아니에요.","내 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#20','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C2',3,'mc','auto','「작은 우산」에서 지후 옷이 젖은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":20,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「작은 우산」에서 지후 옷이 젖은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우산을 할머니 쪽으로 씌워 드렸기 때문에","correct":true},{"t":"우산을 잃어버렸기 때문에","mis":"K1-2-u4-X02"},{"t":"버스를 놓쳤기 때문에","mis":"K1-2-u4-X02"}],"explanation":["우산을 할머니께 씌워 드려서 자기는 조금 맞았어요.","잃어버리거나 놓친 일은 없어요.","앞에 있었던 일."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
