INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#22','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C3',3,'mc','auto','따옴표를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":22,"concept":"K1-2-u4-C3","difficulty":3,"kind":"mc","stem":"따옴표를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","correct":true},{"t":"할머니가 ''고맙다, 꼬마야.'' 하고 웃으셨다.","mis":"K1-2-u4-X06"},{"t":"할머니가 \"고맙다, 꼬마야. 하고 웃으셨다.","mis":"K1-2-u4-X07"}],"explanation":["소리 낸 말은 큰따옴표를 열고 닫아요.","작은따옴표는 마음속 말, 한쪽만은 안 돼요.","두 짝."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#23','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C7',4,'sa','auto','그림을 보고 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#24','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C5',4,'essay','teacher','「작은 우산」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「작은 우산」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 지후가 할머니께 우산을 씌워 드린 장면이 남았다. 자기가 비를 맞으면서도 할머니를 먼저 생각해서 뭉클했다. — 장면 하나와 인물에게서 찾은 까닭이 있으면 맞아요.","scoring_points":["장면이 하나인가","까닭이 인물의 말·행동에서 왔는가","내 말로 썼는가"]},"explanation":["장면 하나, 까닭 하나.","인물이 한 일에서.","어느 장면이든."],"asset":{"type":"passage","lines":["비 오는 날 오후, 지후는 우산을 쓰고 집에 가고 있었다.","버스 정류장에서 할머니가 비를 맞고 서 계셨다.","지후는 할머니 옆에 서서 우산을 씌워 드렸다.","할머니가 \"고맙다, 꼬마야.\" 하고 웃으셨다.","버스가 오자 할머니는 손을 흔들며 타셨다.","저녁에 집에 온 지후는 옷이 조금 젖어 있었다.","지후는 마음속으로 ''그래도 참 잘했어.'' 하고 생각했다."],"title":"「작은 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_c#25','kor',1,2,'u4','','g1_2_kor_u4_review_c','unit_review','K1-2-u4-C4',4,'essay','teacher','「구름 위 우체부 토리」에서 가장 먼저 있었던 일과 가장 나중에 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「구름 위 우체부 토리」에서 가장 먼저 있었던 일과 가장 나중에 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 아침에 토리가 편지 자루를 받았다. 밤에 아이들이 편지를 받고 손을 흔들었다. — 처음·끝이 맞고 문장마다 언제·누가·무엇을이 있으면 맞아요.","scoring_points":["처음과 끝이 맞는가","문장마다 언제·누가·무엇을이 있는가","카드에 없는 일을 넣지 않았는가"]},"explanation":["① 과 ④ 카드.","세 가지씩.","없는 일은 빼요."],"asset":{"type":"passage","lines":["① 아침 — 작은 새 토리는 우체국장 할머니께 편지 자루를 받았다.","② 낮 — 토리는 바람을 가르며 높은 산을 넘었다.","③ 저녁 — 비가 내려 토리는 젖은 편지를 날개로 감싸 말렸다.","④ 밤 — 마을 아이들이 편지를 받고 토리에게 손을 흔들었다."],"title":"「구름 위 우체부 토리」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#1','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',1,'mc','auto','「종이배 경주」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":1,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「종이배 경주」에 나오는 인물은 누구인가요?","options":[{"t":"민솔이와 형","correct":true},{"t":"민솔이와 선생님","mis":"K1-2-u4-X03"},{"t":"지후와 형","mis":"K1-2-u4-X03"}],"explanation":["민솔이와 형이 종이배를 띄웠어요.","선생님·지후는 없어요.","이름을 찾아요."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#2','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',1,'mc','auto','「종이배 경주」에서 때를 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u4-X04']::text[],false,'{"seq":2,"concept":"K1-2-u4-C2","difficulty":1,"kind":"mc","stem":"「종이배 경주」에서 때를 알려 주는 말은 어느 것인가요?","options":[{"t":"일요일 낮","correct":true},{"t":"개울에서","mis":"K1-2-u4-X04"},{"t":"종이배를","mis":"K1-2-u4-X04"}],"explanation":["「언제?」에 답이 되는 말이에요.","개울에서는 어디, 종이배를은 무엇이에요.","때."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#3','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C3',1,'mc','auto','작은따옴표 ‘ ’는 언제 쓰나요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":3,"concept":"K1-2-u4-C3","difficulty":1,"kind":"mc","stem":"작은따옴표 ‘ ’는 언제 쓰나요?","options":[{"t":"마음속으로 한 말을 적을 때","correct":true},{"t":"소리 내어 한 말을 적을 때","mis":"K1-2-u4-X06"},{"t":"때를 알려 주는 말에","mis":"K1-2-u4-X07"}],"explanation":["마음속 말에 써요.","소리 낸 말은 큰따옴표예요.","가슴."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#4','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',1,'mc','auto','「고장 난 로봇 삐삐」에 나오는 인물은 누구인가요?',ARRAY['K1-2-u4-X03']::text[],false,'{"seq":4,"concept":"K1-2-u4-C4","difficulty":1,"kind":"mc","stem":"「고장 난 로봇 삐삐」에 나오는 인물은 누구인가요?","options":[{"t":"삐삐와 다온","correct":true},{"t":"삐삐와 토리","mis":"K1-2-u4-X03"},{"t":"다온과 할머니","mis":"K1-2-u4-X03"}],"explanation":["카드 네 장에 둘이 나와요.","토리·할머니는 없어요.","카드를 봐요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#5','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',1,'mc','auto','마음이 뭉클해지는 것을 무엇이라고 하나요?',ARRAY['K1-2-u4-X04','K1-2-u4-X07']::text[],false,'{"seq":5,"concept":"K1-2-u4-C5","difficulty":1,"kind":"mc","stem":"마음이 뭉클해지는 것을 무엇이라고 하나요?","options":[{"t":"감동","correct":true},{"t":"차례","mis":"K1-2-u4-X04"},{"t":"따옴표","mis":"K1-2-u4-X07"}],"explanation":["뭉클함이 감동이에요.","차례·따옴표는 다른 말이에요.","뭉클."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#6','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',1,'mc','auto','그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12','K1-2-u4-X14']::text[],false,'{"seq":6,"concept":"K1-2-u4-C6","difficulty":1,"kind":"mc","stem":"그림으로 나타낼 장면으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 마음이 움직인 장면","correct":true},{"t":"친구가 고른 장면","mis":"K1-2-u4-X12"},{"t":"제일 쉬운 장면","mis":"K1-2-u4-X14"}],"explanation":["내 감동이에요.","친구 장면·쉬운 장면은 아니에요.","뭉클한 곳."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#7','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',1,'mc','auto','「종이배 경주」에서 형이 한 일은 무엇인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":7,"concept":"K1-2-u4-C1","difficulty":1,"kind":"mc","stem":"「종이배 경주」에서 형이 한 일은 무엇인가요?","options":[{"t":"나뭇가지로 종이배를 밀어 주었다","correct":true},{"t":"종이배를 접었다","mis":"K1-2-u4-X02"},{"t":"개울에 들어갔다","mis":"K1-2-u4-X02"}],"explanation":["배를 밀어 주었어요.","접은 일, 들어간 일은 없어요.","형 줄."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#8','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',1,'mc','auto','동작을 나타내는 말은 어느 것인가요?',ARRAY['K1-2-u4-X17']::text[],false,'{"seq":8,"concept":"K1-2-u4-C7","difficulty":1,"kind":"mc","stem":"동작을 나타내는 말은 어느 것인가요?","options":[{"t":"씻습니다","correct":true},{"t":"손","mis":"K1-2-u4-X17"},{"t":"깨끗하다","mis":"K1-2-u4-X17"}],"explanation":["「씻습니다」는 움직임이에요.","손은 이름, 깨끗하다는 모양이에요.","몸으로 해 볼 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#9','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',2,'match','auto','「종이배 경주」에서 때와 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u4-C2","difficulty":2,"kind":"match","stem":"「종이배 경주」에서 때와 일을 선으로 이어 보세요.","pairs":[{"l":"일요일 낮","r":"종이배를 띄웠다"},{"l":"저녁","r":"두 배가 개울 끝에 닿았다"}],"mis":"K1-2-u4-X05","explanation":["낮에 띄웠어요.","저녁에 닿았어요.","때 옆."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#10','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C1',2,'match','auto','「종이배 경주」에서 인물과 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u4-C1","difficulty":2,"kind":"match","stem":"「종이배 경주」에서 인물과 한 일을 선으로 이어 보세요.","pairs":[{"l":"민솔","r":"종이배가 돌에 걸렸다"},{"l":"형","r":"나뭇가지로 배를 밀었다"}],"mis":"K1-2-u4-X02","explanation":["민솔이 배가 걸렸어요.","형이 밀었어요.","인물마다."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#11','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',2,'mc','auto','「고장 난 로봇 삐삐」에서 가장 나중에 있었던 일은 무엇인가요?',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":11,"concept":"K1-2-u4-C4","difficulty":2,"kind":"mc","stem":"「고장 난 로봇 삐삐」에서 가장 나중에 있었던 일은 무엇인가요?","options":[{"t":"삐삐가 불빛을 깜빡이며 인사했다","correct":true},{"t":"다온이를 태우고 돌았다","mis":"K1-2-u4-X05"},{"t":"바퀴가 빠진 채 서 있었다","mis":"K1-2-u4-X05"}],"explanation":["④ 밤이 마지막이에요.","태우고 돈 것은 저녁, 바퀴는 아침.","카드 번호."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#12','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',2,'mc','auto','감동이 사람마다 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X12','K1-2-u4-X13']::text[],false,'{"seq":12,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"감동이 사람마다 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 겪은 일이 달라서 마음이 움직이는 곳도 달라서","correct":true},{"t":"누가 더 잘 보았는지 달라서","mis":"K1-2-u4-X12"},{"t":"만화를 본 시간이 달라서","mis":"K1-2-u4-X13"}],"explanation":["겪은 일이 달라요.","잘 보고 못 보고가 아니에요.","마음이 움직이는 곳."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#13','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C3',2,'mc','auto','「종이배 경주」에서 큰따옴표 안에 있는 말은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":13,"concept":"K1-2-u4-C3","difficulty":2,"kind":"mc","stem":"「종이배 경주」에서 큰따옴표 안에 있는 말은 어느 것인가요?","options":[{"t":"내가 밀어 줄게.","correct":true},{"t":"형이 있어서 다행이야.","mis":"K1-2-u4-X06"},{"t":"배가 돌에 걸렸다.","mis":"K1-2-u4-X07"}],"explanation":["형이 소리 내어 한 말이에요.","「형이 있어서 다행이야」는 마음속 말이에요.","입."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#14','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',2,'mc','auto','어떤 장면인지 알 수 있는 그림은 어느 것인가요?',ARRAY['K1-2-u4-X14','K1-2-u4-X15']::text[],false,'{"seq":14,"concept":"K1-2-u4-C6","difficulty":2,"kind":"mc","stem":"어떤 장면인지 알 수 있는 그림은 어느 것인가요?","options":[{"t":"형이 나뭇가지로 종이배를 밀어 주는 그림","correct":true},{"t":"테두리만 꾸민 그림","mis":"K1-2-u4-X14"},{"t":"개울만 파랗게 칠한 그림","mis":"K1-2-u4-X15"}],"explanation":["인물과 한 일이 보여요.","테두리·개울만으로는 몰라요.","누가 무엇을."],"asset":{"type":"scene","icon":"🌊⛵🧒","text":"형이 나뭇가지로 종이배를 밀어 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#15','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',2,'ox','auto','「종이배 경주」에서 두 배가 개울 끝에 닿은 일은 배가 돌에 걸린 일보다 나중에 있었어요.',ARRAY['K1-2-u4-X05']::text[],false,'{"seq":15,"concept":"K1-2-u4-C2","difficulty":2,"kind":"ox","stem":"「종이배 경주」에서 두 배가 개울 끝에 닿은 일은 배가 돌에 걸린 일보다 나중에 있었어요.","answer":"O","reason_options":[{"t":"배를 띄우고 돌에 걸린 뒤 「저녁이 되자」 닿았으니까","correct":true},{"t":"개울 끝은 멀기 때문에","mis":"K1-2-u4-X05"}],"mis":"K1-2-u4-X05","explanation":["저녁이 나중이에요.","거리가 아니라 때로 정해요.","낮→저녁."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#16','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',2,'mc','auto','까닭을 함께 말한 친구는 누구인가요?',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":16,"concept":"K1-2-u4-C5","difficulty":2,"kind":"mc","stem":"까닭을 함께 말한 친구는 누구인가요?","options":[{"t":"나린이와 도윤이 둘 다","correct":true},{"t":"나린이만","mis":"K1-2-u4-X10"},{"t":"아무도 없어요","mis":"K1-2-u4-X10"}],"explanation":["둘 다 「~해서」로 까닭을 붙였어요.","도윤이도 「고마운 마음이 느껴져서」라고 했어요.","장면 뒤의 말."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「작은 우산」에서 어느 장면이 가장 마음에 남았나요?"},{"who":"나린","text":"지후가 우산을 씌워 드린 장면이요. 비를 맞으면서도 할머니를 먼저 생각해서요."},{"who":"도윤","text":"나는 할머니가 손을 흔든 장면이요. 고마운 마음이 느껴졌어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
