INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#18','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',3,'error','auto','「고장 난 로봇 삐삐」를 정리한 문장을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#19','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',3,'ox','auto','「감동이었다」 한마디만 말하면 무엇이 어떻게 좋았는지 전해지지 않아요.',ARRAY['K1-2-u4-X10']::text[],false,'{"seq":19,"concept":"K1-2-u4-C5","difficulty":3,"kind":"ox","stem":"「감동이었다」 한마디만 말하면 무엇이 어떻게 좋았는지 전해지지 않아요.","answer":"O","reason_options":[{"t":"까닭이 없으면 마음이 어디에서 움직였는지 보이지 않으니까","correct":true},{"t":"한마디는 너무 짧아서 예의가 없으니까","mis":"K1-2-u4-X10"}],"mis":"K1-2-u4-X10","explanation":["까닭을 붙여요.","예의가 아니라 마음이 안 보여서예요.","무엇이 어떻게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#20','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C2',3,'mc','auto','「종이배 경주」에서 두 배가 나란히 개울 끝에 닿은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u4-X02']::text[],false,'{"seq":20,"concept":"K1-2-u4-C2","difficulty":3,"kind":"mc","stem":"「종이배 경주」에서 두 배가 나란히 개울 끝에 닿은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"형이 멈춘 배를 밀어 주었기 때문에","correct":true},{"t":"바람이 세게 불었기 때문에","mis":"K1-2-u4-X02"},{"t":"민솔이가 배를 다시 접었기 때문에","mis":"K1-2-u4-X02"}],"explanation":["형이 밀어 준 덕분에 다시 갔어요.","바람, 다시 접은 일은 없어요.","앞에 있었던 일."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#21','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C6',3,'error','auto','친구 그림을 보고 한 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#22','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C3',3,'mc','auto','따옴표를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u4-X06','K1-2-u4-X07']::text[],false,'{"seq":22,"concept":"K1-2-u4-C3","difficulty":3,"kind":"mc","stem":"따옴표를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다.","correct":true},{"t":"민솔이는 마음속으로 \"형이 있어서 다행이야.\" 하고 생각했다.","mis":"K1-2-u4-X06"},{"t":"민솔이는 마음속으로 형이 있어서 다행이야.'' 하고 생각했다.","mis":"K1-2-u4-X07"}],"explanation":["마음속 말은 작은따옴표를 열고 닫아요.","큰따옴표는 소리 낸 말, 한쪽만은 안 돼요.","두 짝."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#23','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C7',4,'sa','auto','그림을 보고 빈칸에 알맞은 동작을 나타내는 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#24','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C5',4,'essay','teacher','「종이배 경주」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u4-C5","difficulty":4,"kind":"essay","stem":"「종이배 경주」에서 마음에 남는 장면 하나를 고르고, 인물이 한 일에서 찾은 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 형이 나뭇가지로 배를 밀어 준 장면이 남았다. 동생 배가 멈추자 바로 도와주어서 마음이 따뜻했다. — 장면 하나와 인물에게서 찾은 까닭이 있으면 맞아요.","scoring_points":["장면이 하나인가","까닭이 인물의 말·행동에서 왔는가","내 말로 썼는가"]},"explanation":["장면 하나, 까닭 하나.","인물이 한 일에서.","어느 장면이든."],"asset":{"type":"passage","lines":["일요일 낮, 민솔이와 형은 개울에서 종이배를 띄웠다.","민솔이의 배가 돌에 걸려 멈추었다.","형이 \"내가 밀어 줄게.\" 하고 나뭇가지로 배를 밀었다.","배는 다시 물 위를 미끄러져 갔다.","저녁이 되자 두 배는 나란히 개울 끝에 닿았다.","민솔이는 마음속으로 ''형이 있어서 다행이야.'' 하고 생각했다."],"title":"「종이배 경주」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u4_review_d#25','kor',1,2,'u4','','g1_2_kor_u4_review_d','unit_review','K1-2-u4-C4',4,'essay','teacher','「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일과 가장 나중에 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u4-C4","difficulty":4,"kind":"essay","stem":"「고장 난 로봇 삐삐」에서 가장 먼저 있었던 일과 가장 나중에 있었던 일을 「언제 · 누가 · 무엇을」이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 아침에 삐삐가 바퀴 빠진 채 서 있었다. 밤에 삐삐가 불빛을 깜빡이며 인사했다. — 처음·끝이 맞고 문장마다 언제·누가·무엇을이 있으면 맞아요.","scoring_points":["처음과 끝이 맞는가","문장마다 언제·누가·무엇을이 있는가","카드에 없는 일을 넣지 않았는가"]},"explanation":["① 과 ④ 카드.","세 가지씩.","없는 일은 빼요."],"asset":{"type":"passage","lines":["① 아침 — 로봇 삐삐가 바퀴가 빠진 채 공원에 서 있었다.","② 낮 — 다온이가 삐삐의 바퀴를 찾아 끼워 주었다.","③ 저녁 — 삐삐는 다온이를 태우고 공원을 한 바퀴 돌았다.","④ 밤 — 삐삐는 다온이네 집 앞에서 불빛을 깜빡이며 인사했다."],"title":"「고장 난 로봇 삐삐」 장면 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
